from pathlib import Path
import re

def write(path: str, content: str):
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content)

def replace(path: str, old: str, new: str):
    target = Path(path)
    text = target.read_text()
    if old not in text:
        raise SystemExit(f'Anchor not found in {path}: {old[:120]!r}')
    target.write_text(text.replace(old, new, 1))

def sub(path: str, pattern: str, replacement: str, flags=0):
    target = Path(path)
    text = target.read_text()
    next_text, count = re.subn(pattern, replacement, text, count=1, flags=flags)
    if count != 1:
        raise SystemExit(f'Pattern not found or ambiguous in {path}: {pattern[:120]!r} ({count})')
    target.write_text(next_text)

write('packages/core/src/marketplace-schema.ts', 'export * as MarketplaceSchema from "./marketplace-schema"\n\nimport { Schema } from "effect"\n\nexport const Trust = Schema.Literals(["official", "verified", "community", "private"])\nexport const ConfiguredTrust = Schema.Literals(["community", "private"])\nexport const Kind = Schema.Literals(["plugin", "skill", "agent", "command", "mcp", "bundle"])\n\nexport const Source = Schema.Struct({\n  id: Schema.String,\n  name: Schema.String,\n  url: Schema.String,\n  reference: Schema.optional(Schema.String),\n  enabled: Schema.optional(Schema.Boolean),\n  trust: Schema.optional(Trust),\n  headers: Schema.optional(Schema.Record(Schema.String, Schema.String)),\n}).annotate({ identifier: "MarketplaceSource" })\n\nexport const Installed = Schema.Struct({\n  source: Schema.String,\n  source_url: Schema.optional(Schema.String),\n  source_trust: Schema.optional(Trust),\n  catalog: Schema.String,\n  catalog_name: Schema.optional(Schema.String),\n  item: Schema.String,\n  name: Schema.String,\n  kind: Kind,\n  version: Schema.String,\n  publisher: Schema.optional(Schema.String),\n  fingerprint: Schema.String,\n  installed_at: Schema.String,\n  updated_at: Schema.String,\n  snapshot: Schema.optional(Schema.Unknown),\n  plan: Schema.Unknown,\n  materialized_plan: Schema.optional(Schema.Unknown),\n  active_plan: Schema.optional(Schema.Unknown),\n  receipt: Schema.Unknown,\n  enabled: Schema.optional(Schema.Boolean),\n  disabled_skills: Schema.optional(Schema.Array(Schema.String)),\n  disabled_mcp: Schema.optional(Schema.Array(Schema.String)),\n  catalog_digest: Schema.optional(Schema.String),\n  manifest_digest: Schema.optional(Schema.String),\n  materialized_digest: Schema.optional(Schema.String),\n  artifact_digests: Schema.optional(Schema.Array(Schema.String)),\n}).annotate({ identifier: "MarketplaceInstalled" })\n\nexport const State = Schema.Struct({\n  revision: Schema.optional(Schema.Number),\n  sources: Schema.optional(Schema.Array(Source)),\n  installed: Schema.optional(Schema.Record(Schema.String, Installed)),\n}).annotate({ identifier: "MarketplaceState" })\n\nexport const Listing = Schema.Struct({\n  key: Schema.String,\n  source: Source,\n  catalog: Schema.Unknown,\n  item: Schema.Unknown,\n  orphaned: Schema.optional(Schema.Boolean),\n  catalog_url: Schema.optional(Schema.String),\n  catalog_digest: Schema.optional(Schema.String),\n}).annotate({ identifier: "MarketplaceListing" })\n\nexport const LoadError = Schema.Struct({\n  source: Source,\n  message: Schema.String,\n}).annotate({ identifier: "MarketplaceLoadError" })\n\nexport const CacheSummary = Schema.Struct({\n  root: Schema.String,\n  objects: Schema.Number,\n  total_bytes: Schema.Number,\n  fetch_entries: Schema.Number,\n  materializations: Schema.Number,\n}).annotate({ identifier: "MarketplaceCacheSummary" })\n\nexport const View = Schema.Struct({\n  state: State,\n  listings: Schema.Array(Listing),\n  errors: Schema.Array(LoadError),\n  cache: CacheSummary,\n}).annotate({ identifier: "MarketplaceView" })\n\nexport const Conflict = Schema.Struct({\n  path: Schema.String,\n  current: Schema.Unknown,\n  incoming: Schema.Unknown,\n}).annotate({ identifier: "MarketplaceConflict" })\n\nexport const PlanInput = Schema.Struct({\n  key: Schema.String,\n}).annotate({ identifier: "MarketplacePlanInput" })\n\nexport const PlanResult = Schema.Union([\n  Schema.Struct({\n    ok: Schema.Literal(true),\n    key: Schema.String,\n    action: Schema.Literals(["install", "update"]),\n    trust_warning: Schema.Boolean,\n    conflicts: Schema.Array(Conflict),\n    permissions: Schema.Array(Schema.String),\n    summary: Schema.String,\n  }),\n  Schema.Struct({\n    ok: Schema.Literal(false),\n    reason: Schema.Literals(["not_found", "materialization"]),\n    message: Schema.String,\n  }),\n]).annotate({ identifier: "MarketplacePlanResult" })\n\nexport const InstallInput = Schema.Struct({\n  key: Schema.String,\n  expected_revision: Schema.Number,\n  force: Schema.optional(Schema.Boolean),\n  accept_untrusted: Schema.optional(Schema.Boolean),\n}).annotate({ identifier: "MarketplaceInstallInput" })\n\nexport const UpdateAllInput = Schema.Struct({\n  expected_revision: Schema.Number,\n  force: Schema.optional(Schema.Boolean),\n  accept_untrusted: Schema.optional(Schema.Boolean),\n}).annotate({ identifier: "MarketplaceUpdateAllInput" })\n\nexport const RevisionInput = Schema.Struct({\n  expected_revision: Schema.Number,\n}).annotate({ identifier: "MarketplaceRevisionInput" })\n\nexport const ToggleInput = Schema.Struct({\n  expected_revision: Schema.Number,\n  component: Schema.Literals(["package", "skill", "mcp"]),\n  id: Schema.optional(Schema.String),\n  enabled: Schema.Boolean,\n}).annotate({ identifier: "MarketplaceToggleInput" })\n\nexport const SourceAddInput = Schema.Struct({\n  expected_revision: Schema.Number,\n  url: Schema.String,\n  name: Schema.optional(Schema.String),\n  trust: Schema.optional(ConfiguredTrust),\n  headers: Schema.optional(Schema.Record(Schema.String, Schema.String)),\n}).annotate({ identifier: "MarketplaceSourceAddInput" })\n\nexport const SourceToggleInput = Schema.Struct({\n  expected_revision: Schema.Number,\n  enabled: Schema.Boolean,\n}).annotate({ identifier: "MarketplaceSourceToggleInput" })\n\nexport const ProfileExportInput = Schema.Struct({\n  name: Schema.optional(Schema.String),\n  description: Schema.optional(Schema.String),\n}).annotate({ identifier: "MarketplaceProfileExportInput" })\n\nexport const CachePruneInput = Schema.Struct({\n  max_age_days: Schema.optional(Schema.Number),\n}).annotate({ identifier: "MarketplaceCachePruneInput" })\n\nexport const MutationResult = Schema.Union([\n  Schema.Struct({\n    ok: Schema.Literal(true),\n    changed: Schema.Boolean,\n    view: View,\n    connect_mcp: Schema.Array(Schema.String),\n    preserved: Schema.Array(Schema.String),\n  }),\n  Schema.Struct({\n    ok: Schema.Literal(false),\n    reason: Schema.Literals(["conflict", "revision", "trust", "not_found", "materialization"]),\n    message: Schema.String,\n    revision: Schema.optional(Schema.Number),\n    conflicts: Schema.optional(Schema.Array(Conflict)),\n  }),\n]).annotate({ identifier: "MarketplaceMutationResult" })\n\nexport const Profile = Schema.Unknown.annotate({ identifier: "MarketplaceProfile" })\n')

write('packages/core/src/marketplace/sql.ts', 'import { index, integer, sqliteTable, text } from "drizzle-orm/sqlite-core"\nimport type { MarketplaceInstalled, MarketplaceSource } from "../marketplace"\n\nexport const MarketplaceRegistryTable = sqliteTable("marketplace_registry", {\n  id: integer().primaryKey(),\n  revision: integer().notNull(),\n  time_updated: integer().notNull(),\n})\n\nexport const MarketplaceSourceTable = sqliteTable(\n  "marketplace_source",\n  {\n    id: text().primaryKey(),\n    data: text({ mode: "json" }).$type<MarketplaceSource>().notNull(),\n    position: integer().notNull(),\n    time_created: integer().notNull(),\n    time_updated: integer().notNull(),\n  },\n  (table) => [index("marketplace_source_position_idx").on(table.position)],\n)\n\nexport const MarketplaceInstallTable = sqliteTable(\n  "marketplace_install",\n  {\n    key: text().primaryKey(),\n    data: text({ mode: "json" }).$type<MarketplaceInstalled>().notNull(),\n    position: integer().notNull(),\n    time_created: integer().notNull(),\n    time_updated: integer().notNull(),\n  },\n  (table) => [index("marketplace_install_position_idx").on(table.position)],\n)\n\nexport const MarketplaceArtifactTable = sqliteTable(\n  "marketplace_artifact",\n  {\n    digest: text().primaryKey(),\n    size: integer().notNull(),\n    media_type: text(),\n    kind: text().notNull(),\n    source_url: text(),\n    time_created: integer().notNull(),\n    time_accessed: integer().notNull(),\n  },\n  (table) => [index("marketplace_artifact_accessed_idx").on(table.time_accessed)],\n)\n\nexport const MarketplaceFetchTable = sqliteTable(\n  "marketplace_fetch",\n  {\n    key: text().primaryKey(),\n    url: text().notNull(),\n    digest: text()\n      .notNull()\n      .references(() => MarketplaceArtifactTable.digest, { onDelete: "cascade" }),\n    etag: text(),\n    last_modified: text(),\n    status: integer().notNull(),\n    time_fetched: integer().notNull(),\n  },\n  (table) => [\n    index("marketplace_fetch_digest_idx").on(table.digest),\n    index("marketplace_fetch_time_idx").on(table.time_fetched),\n  ],\n)\n\nexport const MarketplaceMaterializationTable = sqliteTable(\n  "marketplace_materialization",\n  {\n    digest: text().primaryKey(),\n    path: text().notNull(),\n    artifacts: text({ mode: "json" }).$type<string[]>().notNull(),\n    time_created: integer().notNull(),\n    time_accessed: integer().notNull(),\n  },\n  (table) => [index("marketplace_materialization_accessed_idx").on(table.time_accessed)],\n)\n')

write('packages/opencode/src/marketplace/registry.ts', 'import { isDeepStrictEqual } from "util"\nimport { Context, Effect, Layer, Schema } from "effect"\nimport { sql } from "drizzle-orm"\nimport { LayerNode } from "@opencode-ai/core/effect/layer-node"\nimport { Database } from "@opencode-ai/core/database/database"\nimport type { MarketplaceInstalled, MarketplaceSource, MarketplaceState } from "@opencode-ai/core/marketplace"\n\nconst REGISTRY_ID = 1\n\nexport class ConflictError extends Schema.TaggedErrorClass<ConflictError>()("MarketplaceRegistryConflictError", {\n  expected: Schema.Number,\n  actual: Schema.Number,\n}) {\n  override get message() {\n    return `Marketplace registry changed concurrently (expected revision ${this.expected}, actual ${this.actual})`\n  }\n}\n\nexport type ReplaceResult = {\n  state: MarketplaceState\n  changed: boolean\n}\n\nexport interface Interface {\n  readonly read: () => Effect.Effect<MarketplaceState>\n  readonly replace: (state: MarketplaceState) => Effect.Effect<ReplaceResult, ConflictError>\n}\n\nexport class Service extends Context.Service<Service, Interface>()("@opencode/MarketplaceRegistry") {}\n\ntype Executor = Pick<Database.Interface["db"], "all" | "run">\n\nfunction parseJson<T>(value: unknown): T {\n  if (typeof value === "string") return JSON.parse(value) as T\n  return structuredClone(value) as T\n}\n\nfunction normalize(state: MarketplaceState): Omit<MarketplaceState, "revision"> {\n  const value: Omit<MarketplaceState, "revision"> = {}\n  if (state.sources !== undefined) value.sources = structuredClone(state.sources)\n  if (state.installed !== undefined) value.installed = structuredClone(state.installed)\n  return JSON.parse(JSON.stringify(value)) as Omit<MarketplaceState, "revision">\n}\n\nconst layer = Layer.effect(\n  Service,\n  Effect.gen(function* () {\n    const { db } = yield* Database.Service\n\n    const readFrom = Effect.fnUntraced(function* (executor: Executor) {\n      const now = Date.now()\n      yield* executor\n        .run(\n          sql`INSERT OR IGNORE INTO marketplace_registry (id, revision, time_updated)\n              VALUES (${REGISTRY_ID}, 0, ${now})`,\n        )\n        .pipe(Effect.orDie)\n\n      const meta = (\n        yield* executor\n          .all<{ revision: number }>(\n            sql`SELECT revision FROM marketplace_registry WHERE id = ${REGISTRY_ID} LIMIT 1`,\n          )\n          .pipe(Effect.orDie)\n      )[0]\n\n      const sourceRows = yield* executor\n        .all<{ data: unknown }>(sql`SELECT data FROM marketplace_source ORDER BY position ASC, id ASC`)\n        .pipe(Effect.orDie)\n      const installRows = yield* executor\n        .all<{ key: string; data: unknown }>(\n          sql`SELECT key, data FROM marketplace_install ORDER BY position ASC, key ASC`,\n        )\n        .pipe(Effect.orDie)\n\n      const sources = sourceRows.map((row) => parseJson<MarketplaceSource>(row.data))\n      const installed = Object.fromEntries(\n        installRows.map((row) => [row.key, parseJson<MarketplaceInstalled>(row.data)] as const),\n      )\n\n      return {\n        revision: meta?.revision ?? 0,\n        ...(sources.length ? { sources } : {}),\n        ...(installRows.length ? { installed } : {}),\n      } satisfies MarketplaceState\n    })\n\n    const read = Effect.fn("MarketplaceRegistry.read")(function* () {\n      return yield* readFrom(db)\n    })\n\n    const replace = Effect.fn("MarketplaceRegistry.replace")(function* (state: MarketplaceState) {\n      return yield* db.transaction((tx) =>\n        Effect.gen(function* () {\n          const current = yield* readFrom(tx as unknown as Executor)\n          const desired = normalize(state)\n          const existing = normalize(current)\n          if (isDeepStrictEqual(existing, desired)) return { state: current, changed: false }\n\n          const expected = state.revision ?? 0\n          const actual = current.revision ?? 0\n          if (expected !== actual) return yield* new ConflictError({ expected, actual })\n\n          const now = Date.now()\n          const revision = actual + 1\n          yield* tx\n            .run(\n              sql`UPDATE marketplace_registry\n                  SET revision = ${revision}, time_updated = ${now}\n                  WHERE id = ${REGISTRY_ID}`,\n            )\n            .pipe(Effect.orDie)\n          yield* tx.run(sql`DELETE FROM marketplace_source`).pipe(Effect.orDie)\n          yield* tx.run(sql`DELETE FROM marketplace_install`).pipe(Effect.orDie)\n\n          for (const [position, source] of (desired.sources ?? []).entries()) {\n            yield* tx\n              .run(\n                sql`INSERT INTO marketplace_source (id, data, position, time_created, time_updated)\n                    VALUES (${source.id}, ${JSON.stringify(source)}, ${position}, ${now}, ${now})`,\n              )\n              .pipe(Effect.orDie)\n          }\n\n          for (const [position, [key, installed]] of Object.entries(desired.installed ?? {}).entries()) {\n            yield* tx\n              .run(\n                sql`INSERT INTO marketplace_install (key, data, position, time_created, time_updated)\n                    VALUES (${key}, ${JSON.stringify(installed)}, ${position}, ${now}, ${now})`,\n              )\n              .pipe(Effect.orDie)\n          }\n\n          return {\n            state: {\n              ...structuredClone(desired),\n              revision,\n            },\n            changed: true,\n          }\n        }),\n      )\n    })\n\n    return Service.of({ read, replace })\n  }),\n)\n\nexport const node = LayerNode.make({\n  service: Service,\n  layer,\n  deps: [Database.node],\n})\n')

write('packages/opencode/src/marketplace/cache.ts', 'import path from "path"\nimport fsNode from "fs/promises"\nimport { createHash, randomUUID } from "crypto"\nimport { Context, Effect, Layer, Schema } from "effect"\nimport { sql } from "drizzle-orm"\nimport { LayerNode } from "@opencode-ai/core/effect/layer-node"\nimport { Database } from "@opencode-ai/core/database/database"\nimport { EffectFlock } from "@opencode-ai/core/util/effect-flock"\nimport { Global } from "@opencode-ai/core/global"\nimport type {\n  MarketplaceFetch,\n  MarketplaceInstallPlan,\n  MarketplaceSource,\n  MarketplaceSkill,\n} from "@opencode-ai/core/marketplace"\n\nexport type CacheMode = "cache-first" | "refresh"\n\nexport type Artifact = {\n  digest: string\n  path: string\n  size: number\n  mediaType?: string\n  kind: string\n  sourceUrl?: string\n}\n\nexport type MaterializedPlan = {\n  plan: MarketplaceInstallPlan\n  artifactDigests: string[]\n  treeDigest?: string\n}\n\nexport type CacheSummary = {\n  root: string\n  objects: number\n  total_bytes: number\n  fetch_entries: number\n  materializations: number\n}\n\nexport class CacheError extends Schema.TaggedErrorClass<CacheError>()("MarketplaceCacheError", {\n  operation: Schema.String,\n  message: Schema.String,\n}) {}\n\nexport interface Interface {\n  readonly put: (\n    bytes: Uint8Array,\n    metadata?: { mediaType?: string; kind?: string; sourceUrl?: string },\n  ) => Effect.Effect<Artifact, CacheError>\n  readonly putJson: (\n    value: unknown,\n    metadata?: { kind?: string; sourceUrl?: string },\n  ) => Effect.Effect<Artifact, CacheError>\n  readonly fetchResponse: (input: {\n    url: string\n    headers?: HeadersInit\n    signal?: AbortSignal\n    kind?: string\n    mode?: CacheMode\n  }) => Effect.Effect<Response, CacheError>\n  readonly fetcher: (mode?: CacheMode) => MarketplaceFetch\n  readonly materializePlan: (\n    plan: MarketplaceInstallPlan,\n    source: MarketplaceSource,\n  ) => Effect.Effect<MaterializedPlan, CacheError>\n  readonly summary: () => Effect.Effect<CacheSummary>\n  readonly prune: (input: {\n    keep?: Iterable<string>\n    maxAgeDays?: number\n  }) => Effect.Effect<{ removed_objects: number; removed_materializations: number; summary: CacheSummary }, CacheError>\n}\n\nexport class Service extends Context.Service<Service, Interface>()("@opencode/MarketplaceCache") {}\n\ntype FetchRow = {\n  key: string\n  url: string\n  digest: string\n  etag?: string | null\n  last_modified?: string | null\n  status: number\n  time_fetched: number\n}\n\ntype TreeEntry = {\n  relative: string\n  bytes: Uint8Array\n  digest: string\n}\n\ntype IndexedSkill = {\n  name: string\n  files: string[]\n  version?: string\n}\n\nfunction hashBytes(bytes: Uint8Array) {\n  return createHash("sha256").update(bytes).digest("hex")\n}\n\nfunction digestOf(bytes: Uint8Array) {\n  return `sha256:${hashBytes(bytes)}`\n}\n\nfunction digestHex(digest: string) {\n  const match = /^sha256:([a-f0-9]{64})$/i.exec(digest)\n  if (!match) throw new Error(`Unsupported marketplace digest: ${digest}`)\n  return match[1]!.toLowerCase()\n}\n\nfunction stable(value: unknown): string {\n  if (Array.isArray(value)) return `[${value.map(stable).join(",")}]`\n  if (value && typeof value === "object") {\n    return `{${Object.entries(value as Record<string, unknown>)\n      .sort(([left], [right]) => left.localeCompare(right))\n      .map(([key, item]) => `${JSON.stringify(key)}:${stable(item)}`)\n      .join(",")}}`\n  }\n  return JSON.stringify(value) ?? "null"\n}\n\nfunction cacheError(operation: string, error: unknown) {\n  return error instanceof CacheError\n    ? error\n    : new CacheError({ operation, message: error instanceof Error ? error.message : String(error) })\n}\n\nfunction safeSegment(value: string) {\n  const cleaned = value\n    .normalize("NFKD")\n    .replace(/[^a-zA-Z0-9._-]+/g, "-")\n    .replace(/^-+|-+$/g, "")\n  return cleaned || "item"\n}\n\nfunction safeRelative(value: string) {\n  const clean = value.replaceAll("\\\\", "/").replace(/^\\.\\/+/, "")\n  if (!clean || clean.startsWith("/") || /^[A-Za-z]:\\//.test(clean)) throw new Error(`Unsafe artifact path: ${value}`)\n  const parts = clean.split("/")\n  if (parts.some((part) => !part || part === "." || part === "..")) throw new Error(`Unsafe artifact path: ${value}`)\n  return parts.join("/")\n}\n\nfunction headersObject(input?: HeadersInit) {\n  const headers = new Headers(input)\n  return Object.fromEntries(\n    Array.from(headers.entries())\n      .map(([key, value]) => [key.toLowerCase(), value] as const)\n      .sort(([left], [right]) => left.localeCompare(right)),\n  )\n}\n\nfunction requestKey(url: string, headers?: HeadersInit) {\n  return hashBytes(new TextEncoder().encode(stable({ url, headers: headersObject(headers) })))\n}\n\nfunction sameOriginHeaders(source: MarketplaceSource, target: string) {\n  if (!source.headers) return undefined\n  try {\n    const left = new URL(source.url)\n    const right = new URL(target)\n    return left.origin === right.origin ? source.headers : undefined\n  } catch {\n    return undefined\n  }\n}\n\nfunction readIndex(value: unknown): IndexedSkill[] {\n  if (!value || typeof value !== "object" || !("skills" in value) || !Array.isArray(value.skills)) {\n    throw new Error("Skill source index must contain a skills array")\n  }\n  return value.skills.map((entry, index) => {\n    if (!entry || typeof entry !== "object") throw new Error(`Invalid skill index entry ${index}`)\n    const record = entry as Record<string, unknown>\n    if (typeof record.name !== "string" || !Array.isArray(record.files)) {\n      throw new Error(`Invalid skill index entry ${index}`)\n    }\n    const files = record.files.map((file) => {\n      if (typeof file !== "string") throw new Error(`Invalid skill index file in entry ${index}`)\n      return safeRelative(file)\n    })\n    if (!files.includes("SKILL.md")) throw new Error(`Skill ${record.name} does not contain SKILL.md`)\n    return {\n      name: record.name,\n      files,\n      ...(typeof record.version === "string" ? { version: record.version } : {}),\n    }\n  })\n}\n\nfunction clone<T>(value: T): T {\n  return structuredClone(value)\n}\n\nconst layer = Layer.effect(\n  Service,\n  Effect.gen(function* () {\n    const { db } = yield* Database.Service\n    const flock = yield* EffectFlock.Service\n    const root = path.join(Global.Path.cache, "marketplace")\n    const objects = path.join(root, "objects", "sha256")\n    const materialized = path.join(root, "materialized", "sha256")\n\n    const objectPath = (digest: string) => {\n      const hex = digestHex(digest)\n      return path.join(objects, hex.slice(0, 2), hex)\n    }\n\n    const exists = (target: string) =>\n      Effect.tryPromise({\n        try: () => fsNode.stat(target).then(() => true).catch((error: NodeJS.ErrnoException) => {\n          if (error.code === "ENOENT") return false\n          throw error\n        }),\n        catch: (error) => cacheError("stat", error),\n      })\n\n    const readBytes = (target: string) =>\n      Effect.tryPromise({\n        try: () => fsNode.readFile(target).then((value) => new Uint8Array(value)),\n        catch: (error) => cacheError("read", error),\n      })\n\n    const put = Effect.fn("MarketplaceCache.put")(function* (\n      bytes: Uint8Array,\n      metadata: { mediaType?: string; kind?: string; sourceUrl?: string } = {},\n    ) {\n      const digest = digestOf(bytes)\n      const target = objectPath(digest)\n      yield* flock\n        .withLock(\n          Effect.gen(function* () {\n            if (!(yield* exists(target))) {\n              const staging = `${target}.tmp-${randomUUID()}`\n              yield* Effect.tryPromise({\n                try: async () => {\n                  await fsNode.mkdir(path.dirname(target), { recursive: true })\n                  await fsNode.writeFile(staging, bytes, { mode: 0o600 })\n                  await fsNode.rename(staging, target).catch(async (error: NodeJS.ErrnoException) => {\n                    if (error.code !== "EEXIST") throw error\n                  })\n                  await fsNode.rm(staging, { force: true })\n                },\n                catch: (error) => cacheError("put", error),\n              })\n            }\n\n            const now = Date.now()\n            yield* db\n              .run(sql`\n                INSERT INTO marketplace_artifact\n                  (digest, size, media_type, kind, source_url, time_created, time_accessed)\n                VALUES\n                  (${digest}, ${bytes.byteLength}, ${metadata.mediaType ?? null}, ${metadata.kind ?? "blob"},\n                   ${metadata.sourceUrl ?? null}, ${now}, ${now})\n                ON CONFLICT(digest) DO UPDATE SET\n                  time_accessed = excluded.time_accessed,\n                  media_type = COALESCE(marketplace_artifact.media_type, excluded.media_type),\n                  source_url = COALESCE(marketplace_artifact.source_url, excluded.source_url)\n              `)\n              .pipe(Effect.orDie)\n          }),\n          `marketplace-artifact:${digest}`,\n        )\n        .pipe(Effect.mapError((error) => cacheError("lock", error)))\n\n      return {\n        digest,\n        path: target,\n        size: bytes.byteLength,\n        ...(metadata.mediaType ? { mediaType: metadata.mediaType } : {}),\n        kind: metadata.kind ?? "blob",\n        ...(metadata.sourceUrl ? { sourceUrl: metadata.sourceUrl } : {}),\n      } satisfies Artifact\n    })\n\n    const putJson = Effect.fn("MarketplaceCache.putJson")(function* (\n      value: unknown,\n      metadata: { kind?: string; sourceUrl?: string } = {},\n    ) {\n      return yield* put(new TextEncoder().encode(stable(value)), {\n        mediaType: "application/json",\n        kind: metadata.kind ?? "json",\n        sourceUrl: metadata.sourceUrl,\n      })\n    })\n\n    const cached = Effect.fnUntraced(function* (row: FetchRow | undefined) {\n      if (!row) return undefined\n      const target = objectPath(row.digest)\n      if (!(yield* exists(target))) return undefined\n      const bytes = yield* readBytes(target)\n      const artifact = (\n        yield* db\n          .all<{ media_type?: string | null }>(\n            sql`SELECT media_type FROM marketplace_artifact WHERE digest = ${row.digest} LIMIT 1`,\n          )\n          .pipe(Effect.orDie)\n      )[0]\n      yield* db\n        .run(sql`UPDATE marketplace_artifact SET time_accessed = ${Date.now()} WHERE digest = ${row.digest}`)\n        .pipe(Effect.orDie)\n      return { bytes, mediaType: artifact?.media_type ?? undefined }\n    })\n\n    const fetchResponse = Effect.fn("MarketplaceCache.fetchResponse")(function* (input: {\n      url: string\n      headers?: HeadersInit\n      signal?: AbortSignal\n      kind?: string\n      mode?: CacheMode\n    }) {\n      const url = new URL(input.url).href\n      const key = requestKey(url, input.headers)\n      const row = (\n        yield* db\n          .all<FetchRow>(sql`SELECT * FROM marketplace_fetch WHERE key = ${key} LIMIT 1`)\n          .pipe(Effect.orDie)\n      )[0]\n      const hit = yield* cached(row)\n\n      if (hit && input.mode !== "refresh") {\n        return new Response(hit.bytes, {\n          status: 200,\n          headers: {\n            ...(hit.mediaType ? { "content-type": hit.mediaType } : {}),\n            "content-length": String(hit.bytes.byteLength),\n            "x-opencode-artifact-digest": row!.digest,\n            "x-opencode-cache": "hit",\n          },\n        })\n      }\n\n      const headers = new Headers(input.headers)\n      if (row?.etag) headers.set("if-none-match", row.etag)\n      if (row?.last_modified) headers.set("if-modified-since", row.last_modified)\n\n      const attempt = yield* Effect.tryPromise({\n        try: () => globalThis.fetch(url, { headers, signal: input.signal }),\n        catch: (error) => cacheError("fetch", error),\n      }).pipe(\n        Effect.map((response) => ({ ok: true as const, response })),\n        Effect.catch((error) => Effect.succeed({ ok: false as const, error })),\n      )\n\n      if (!attempt.ok) {\n        if (hit) {\n          return new Response(hit.bytes, {\n            status: 200,\n            headers: {\n              ...(hit.mediaType ? { "content-type": hit.mediaType } : {}),\n              "content-length": String(hit.bytes.byteLength),\n              "x-opencode-artifact-digest": row!.digest,\n              "x-opencode-cache": "stale",\n            },\n          })\n        }\n        return yield* attempt.error\n      }\n\n      const response = attempt.response\n      if (response.status === 304 && hit && row) {\n        yield* db\n          .run(sql`UPDATE marketplace_fetch SET time_fetched = ${Date.now()} WHERE key = ${key}`)\n          .pipe(Effect.orDie)\n        return new Response(hit.bytes, {\n          status: 200,\n          headers: {\n            ...(hit.mediaType ? { "content-type": hit.mediaType } : {}),\n            "content-length": String(hit.bytes.byteLength),\n            "x-opencode-artifact-digest": row.digest,\n            "x-opencode-cache": "revalidated",\n          },\n        })\n      }\n\n      if (!response.ok) {\n        if (hit && row) {\n          return new Response(hit.bytes, {\n            status: 200,\n            headers: {\n              ...(hit.mediaType ? { "content-type": hit.mediaType } : {}),\n              "content-length": String(hit.bytes.byteLength),\n              "x-opencode-artifact-digest": row.digest,\n              "x-opencode-cache": "stale",\n            },\n          })\n        }\n        return yield* new CacheError({\n          operation: "fetch",\n          message: `HTTP ${response.status} ${response.statusText} for ${url}`,\n        })\n      }\n\n      const bytes = yield* Effect.tryPromise({\n        try: () => response.arrayBuffer().then((buffer) => new Uint8Array(buffer)),\n        catch: (error) => cacheError("read response", error),\n      })\n      const mediaType = response.headers.get("content-type") ?? undefined\n      const artifact = yield* put(bytes, { mediaType, kind: input.kind ?? "remote", sourceUrl: url })\n      const now = Date.now()\n      yield* db\n        .run(sql`\n          INSERT INTO marketplace_fetch (key, url, digest, etag, last_modified, status, time_fetched)\n          VALUES (${key}, ${url}, ${artifact.digest}, ${response.headers.get("etag")},\n                  ${response.headers.get("last-modified")}, ${response.status}, ${now})\n          ON CONFLICT(key) DO UPDATE SET\n            url = excluded.url,\n            digest = excluded.digest,\n            etag = excluded.etag,\n            last_modified = excluded.last_modified,\n            status = excluded.status,\n            time_fetched = excluded.time_fetched\n        `)\n        .pipe(Effect.orDie)\n\n      return new Response(bytes, {\n        status: 200,\n        headers: {\n          ...(mediaType ? { "content-type": mediaType } : {}),\n          "content-length": String(bytes.byteLength),\n          "x-opencode-artifact-digest": artifact.digest,\n          "x-opencode-cache": "miss",\n        },\n      })\n    })\n\n    const fetchArtifact = Effect.fnUntraced(function* (input: {\n      url: string\n      headers?: HeadersInit\n      kind: string\n    }) {\n      const response = yield* fetchResponse({ ...input, mode: "refresh" })\n      const bytes = yield* Effect.tryPromise({\n        try: () => response.arrayBuffer().then((buffer) => new Uint8Array(buffer)),\n        catch: (error) => cacheError("read cached response", error),\n      })\n      const digest = response.headers.get("x-opencode-artifact-digest")\n      if (!digest) return yield* new CacheError({ operation: "fetch", message: `Missing digest for ${input.url}` })\n      return { bytes, digest, mediaType: response.headers.get("content-type") ?? undefined }\n    })\n\n    const fetcher = (mode: CacheMode = "cache-first"): MarketplaceFetch => {\n      return async (input, init) => {\n        const request = input instanceof Request ? input : new Request(input, init)\n        return Effect.runPromise(\n          fetchResponse({\n            url: request.url,\n            headers: request.headers,\n            signal: request.signal,\n            kind: "catalog",\n            mode,\n          }),\n        )\n      }\n    }\n\n    const indexedSkill = Effect.fnUntraced(function* (input: {\n      url: string\n      source: MarketplaceSource\n      prefix: string\n      name?: string\n      entries: Map<string, TreeEntry>\n      digests: Set<string>\n    }) {\n      const base = input.url.endsWith("/") ? input.url : `${input.url}/`\n      const indexURL = new URL("index.json", base).href\n      const headers = sameOriginHeaders(input.source, indexURL)\n      const indexArtifact = yield* fetchArtifact({ url: indexURL, headers, kind: "skill-index" })\n      input.digests.add(indexArtifact.digest)\n      const index = yield* Effect.try({\n        try: () => readIndex(JSON.parse(new TextDecoder().decode(indexArtifact.bytes))),\n        catch: (error) => cacheError("parse skill index", error),\n      })\n      const selected = input.name ? index.filter((skill) => skill.name === input.name) : index\n      if (selected.length === 0) {\n        return yield* new CacheError({\n          operation: "materialize skill",\n          message: `Skill ${input.name} is not present in ${indexURL}`,\n        })\n      }\n\n      const roots: Array<{ name: string; relative: string }> = []\n      for (const skill of selected) {\n        const skillRoot = path.posix.join(input.prefix, safeSegment(skill.name))\n        for (const file of skill.files) {\n          const url = new URL(file, `${base}${encodeURIComponent(skill.name)}/`).href\n          const artifact = yield* fetchArtifact({\n            url,\n            headers: sameOriginHeaders(input.source, url),\n            kind: "skill-file",\n          })\n          input.digests.add(artifact.digest)\n          const relative = path.posix.join(skillRoot, safeRelative(file))\n          input.entries.set(relative, { relative, bytes: artifact.bytes, digest: artifact.digest })\n        }\n        roots.push({ name: skill.name, relative: skillRoot })\n      }\n      return roots\n    })\n\n    const directSkill = Effect.fnUntraced(function* (input: {\n      item: MarketplaceSkill\n      source: MarketplaceSource\n      prefix: string\n      entries: Map<string, TreeEntry>\n      digests: Set<string>\n    }) {\n      const url = input.item.url!\n      const artifact = yield* fetchArtifact({\n        url,\n        headers: sameOriginHeaders(input.source, url),\n        kind: "skill-file",\n      })\n      input.digests.add(artifact.digest)\n      const root = path.posix.join(input.prefix, safeSegment(input.item.id || input.item.name))\n      const relative = path.posix.join(root, "SKILL.md")\n      input.entries.set(relative, { relative, bytes: artifact.bytes, digest: artifact.digest })\n      return { name: input.item.name, relative: root }\n    })\n\n    const materializePlan = Effect.fn("MarketplaceCache.materializePlan")(function* (\n      inputPlan: MarketplaceInstallPlan,\n      source: MarketplaceSource,\n    ) {\n      const plan = clone(inputPlan)\n      const entries = new Map<string, TreeEntry>()\n      const digests = new Set<string>()\n      const legacyRoots: string[] = []\n      const itemRoots = new Map<string, string>()\n\n      for (const [index, url] of (plan.skills?.urls ?? []).entries()) {\n        const roots = yield* indexedSkill({\n          url,\n          source,\n          prefix: path.posix.join("skills", `source-${index}`),\n          entries,\n          digests,\n        })\n        legacyRoots.push(...roots.map((root) => root.relative))\n      }\n\n      for (const item of plan.skills?.items ?? []) {\n        if (!item.url) continue\n        const indexed = yield* indexedSkill({\n          url: item.url,\n          source,\n          prefix: path.posix.join("skills", `item-${safeSegment(item.id)}`),\n          name: item.name,\n          entries,\n          digests,\n        }).pipe(\n          Effect.map((roots) => ({ ok: true as const, roots })),\n          Effect.catch(() =>\n            directSkill({\n              item,\n              source,\n              prefix: path.posix.join("skills", `item-${safeSegment(item.id)}`),\n              entries,\n              digests,\n            }).pipe(Effect.map((root) => ({ ok: true as const, roots: [root] }))),\n          ),\n        )\n        const root = indexed.roots[0]\n        if (root) itemRoots.set(item.id, root.relative)\n      }\n\n      const instructionRelatives = new Map<number, string>()\n      for (const [index, instruction] of (plan.instructions ?? []).entries()) {\n        if (!/^https?:\\/\\//i.test(instruction)) continue\n        const url = new URL(instruction).href\n        const artifact = yield* fetchArtifact({\n          url,\n          headers: sameOriginHeaders(source, url),\n          kind: "instruction",\n        })\n        digests.add(artifact.digest)\n        const basename = safeSegment(path.posix.basename(new URL(url).pathname) || `instruction-${index}.md`)\n        const relative = path.posix.join("instructions", `${index}-${basename}`)\n        entries.set(relative, { relative, bytes: artifact.bytes, digest: artifact.digest })\n        instructionRelatives.set(index, relative)\n      }\n\n      if (entries.size === 0) {\n        return { plan, artifactDigests: Array.from(digests).toSorted() } satisfies MaterializedPlan\n      }\n\n      const manifest = Array.from(entries.values())\n        .map((entry) => ({ path: entry.relative, digest: entry.digest }))\n        .toSorted((left, right) => left.path.localeCompare(right.path))\n      const treeDigest = digestOf(new TextEncoder().encode(stable(manifest)))\n      const hex = digestHex(treeDigest)\n      const target = path.join(materialized, hex.slice(0, 2), hex)\n\n      yield* flock\n        .withLock(\n          Effect.gen(function* () {\n            if (!(yield* exists(target))) {\n              const staging = `${target}.tmp-${randomUUID()}`\n              yield* Effect.tryPromise({\n                try: async () => {\n                  for (const entry of entries.values()) {\n                    const file = path.join(staging, ...entry.relative.split("/"))\n                    await fsNode.mkdir(path.dirname(file), { recursive: true })\n                    await fsNode.writeFile(file, entry.bytes, { mode: 0o600 })\n                  }\n                  await fsNode.mkdir(path.dirname(target), { recursive: true })\n                  await fsNode.rename(staging, target).catch(async (error: NodeJS.ErrnoException) => {\n                    if (error.code !== "EEXIST") throw error\n                  })\n                  await fsNode.rm(staging, { recursive: true, force: true })\n                },\n                catch: (error) => cacheError("materialize", error),\n              })\n            }\n\n            const now = Date.now()\n            yield* db\n              .run(sql`\n                INSERT INTO marketplace_materialization\n                  (digest, path, artifacts, time_created, time_accessed)\n                VALUES (${treeDigest}, ${target}, ${JSON.stringify(Array.from(digests).toSorted())}, ${now}, ${now})\n                ON CONFLICT(digest) DO UPDATE SET time_accessed = excluded.time_accessed\n              `)\n              .pipe(Effect.orDie)\n          }),\n          `marketplace-materialization:${treeDigest}`,\n        )\n        .pipe(Effect.mapError((error) => cacheError("materialize lock", error)))\n\n      if (plan.skills) {\n        const existing = plan.skills.paths ?? []\n        plan.skills.paths = Array.from(\n          new Set([...existing, ...legacyRoots.map((relative) => path.join(target, ...relative.split("/")))]),\n        )\n        delete plan.skills.urls\n        if (plan.skills.items) {\n          plan.skills.items = plan.skills.items.map((item) => {\n            const relative = itemRoots.get(item.id)\n            if (!relative) return item\n            const next = { ...item, path: path.join(target, ...relative.split("/")) }\n            delete next.url\n            return next\n          })\n        }\n      }\n\n      if (plan.instructions) {\n        plan.instructions = plan.instructions.map((instruction, index) => {\n          const relative = instructionRelatives.get(index)\n          return relative ? path.join(target, ...relative.split("/")) : instruction\n        })\n      }\n\n      return {\n        plan,\n        artifactDigests: Array.from(digests).toSorted(),\n        treeDigest,\n      } satisfies MaterializedPlan\n    })\n\n    const summary = Effect.fn("MarketplaceCache.summary")(function* () {\n      const artifact = (\n        yield* db\n          .all<{ objects: number; total_bytes: number }>(\n            sql`SELECT COUNT(*) AS objects, COALESCE(SUM(size), 0) AS total_bytes FROM marketplace_artifact`,\n          )\n          .pipe(Effect.orDie)\n      )[0] ?? { objects: 0, total_bytes: 0 }\n      const fetches = (\n        yield* db\n          .all<{ count: number }>(sql`SELECT COUNT(*) AS count FROM marketplace_fetch`)\n          .pipe(Effect.orDie)\n      )[0]?.count ?? 0\n      const trees = (\n        yield* db\n          .all<{ count: number }>(sql`SELECT COUNT(*) AS count FROM marketplace_materialization`)\n          .pipe(Effect.orDie)\n      )[0]?.count ?? 0\n      return {\n        root,\n        objects: Number(artifact.objects),\n        total_bytes: Number(artifact.total_bytes),\n        fetch_entries: Number(fetches),\n        materializations: Number(trees),\n      }\n    })\n\n    const prune = Effect.fn("MarketplaceCache.prune")(function* (input: {\n      keep?: Iterable<string>\n      maxAgeDays?: number\n    }) {\n      const keep = new Set(input.keep ?? [])\n      const cutoff = Date.now() - Math.max(0, input.maxAgeDays ?? 30) * 24 * 60 * 60 * 1000\n      const artifacts = yield* db\n        .all<{ digest: string; time_accessed: number }>(\n          sql`SELECT digest, time_accessed FROM marketplace_artifact WHERE time_accessed < ${cutoff}`,\n        )\n        .pipe(Effect.orDie)\n      const trees = yield* db\n        .all<{ digest: string; path: string; time_accessed: number }>(\n          sql`SELECT digest, path, time_accessed FROM marketplace_materialization WHERE time_accessed < ${cutoff}`,\n        )\n        .pipe(Effect.orDie)\n\n      let removedObjects = 0\n      for (const artifact of artifacts) {\n        if (keep.has(artifact.digest)) continue\n        yield* Effect.tryPromise({\n          try: () => fsNode.rm(objectPath(artifact.digest), { force: true }),\n          catch: (error) => cacheError("prune object", error),\n        })\n        yield* db\n          .run(sql`DELETE FROM marketplace_artifact WHERE digest = ${artifact.digest}`)\n          .pipe(Effect.orDie)\n        removedObjects++\n      }\n\n      let removedMaterializations = 0\n      for (const tree of trees) {\n        if (keep.has(tree.digest)) continue\n        yield* Effect.tryPromise({\n          try: () => fsNode.rm(tree.path, { recursive: true, force: true }),\n          catch: (error) => cacheError("prune materialization", error),\n        })\n        yield* db\n          .run(sql`DELETE FROM marketplace_materialization WHERE digest = ${tree.digest}`)\n          .pipe(Effect.orDie)\n        removedMaterializations++\n      }\n\n      return {\n        removed_objects: removedObjects,\n        removed_materializations: removedMaterializations,\n        summary: yield* summary(),\n      }\n    })\n\n    return Service.of({\n      put,\n      putJson,\n      fetchResponse,\n      fetcher,\n      materializePlan,\n      summary,\n      prune,\n    })\n  }),\n)\n\nexport const node = LayerNode.make({\n  service: Service,\n  layer,\n  deps: [Database.node, EffectFlock.node],\n})\n')

write('packages/opencode/src/marketplace/service.ts', 'import { Context, Effect, Layer } from "effect"\nimport { LayerNode } from "@opencode-ai/core/effect/layer-node"\nimport {\n  createMarketplaceSource,\n  loadMarketplace,\n  marketplaceActivePlan,\n  marketplaceConflicts,\n  marketplaceEnabledMcpNames,\n  marketplaceFingerprint,\n  marketplaceInitialDisabledMcp,\n  marketplacePermissions,\n  marketplacePlanSummary,\n  marketplaceSkillComponents,\n  marketplaceSnapshot,\n  marketplaceStatus,\n  removeMarketplaceSource,\n  toggleMarketplaceSource,\n  upsertMarketplaceSource,\n  type MarketplaceConfiguredTrust,\n  type MarketplaceHostConfig,\n  type MarketplaceInstalled,\n  type MarketplaceListing,\n  type MarketplaceMutationResult,\n  type MarketplacePlanResult,\n  type MarketplaceSource,\n  type MarketplaceState,\n  type MarketplaceView,\n} from "@opencode-ai/core/marketplace"\nimport { exportMarketplaceProfile } from "@opencode-ai/core/marketplace-profile"\nimport { Config } from "@/config/config"\nimport { composeMarketplaceConfig } from "./overlay"\nimport * as MarketplaceRegistry from "./registry"\nimport * as MarketplaceCache from "./cache"\n\nexport type InstallInput = {\n  key: string\n  expectedRevision: number\n  force?: boolean\n  acceptUntrusted?: boolean\n}\n\nexport type UpdateAllInput = {\n  expectedRevision: number\n  force?: boolean\n  acceptUntrusted?: boolean\n}\n\nexport type ToggleInput = {\n  key: string\n  expectedRevision: number\n  component: "package" | "skill" | "mcp"\n  id?: string\n  enabled: boolean\n}\n\nexport type SourceAddInput = {\n  expectedRevision: number\n  url: string\n  name?: string\n  trust?: MarketplaceConfiguredTrust\n  headers?: Record<string, string>\n}\n\nexport interface Interface {\n  readonly get: (options?: { refresh?: boolean }) => Effect.Effect<MarketplaceView>\n  readonly plan: (key: string) => Effect.Effect<MarketplacePlanResult>\n  readonly install: (input: InstallInput) => Effect.Effect<MarketplaceMutationResult>\n  readonly updateAll: (input: UpdateAllInput) => Effect.Effect<MarketplaceMutationResult>\n  readonly uninstall: (input: {\n    key: string\n    expectedRevision: number\n  }) => Effect.Effect<MarketplaceMutationResult>\n  readonly toggle: (input: ToggleInput) => Effect.Effect<MarketplaceMutationResult>\n  readonly sourceAdd: (input: SourceAddInput) => Effect.Effect<MarketplaceMutationResult>\n  readonly sourceToggle: (input: {\n    id: string\n    expectedRevision: number\n    enabled: boolean\n  }) => Effect.Effect<MarketplaceMutationResult>\n  readonly sourceRemove: (input: {\n    id: string\n    expectedRevision: number\n  }) => Effect.Effect<MarketplaceMutationResult>\n  readonly profileExport: (input?: { name?: string; description?: string }) => Effect.Effect<unknown>\n  readonly cachePrune: (input?: { maxAgeDays?: number }) => Effect.Effect<MarketplaceView["cache"]>\n}\n\nexport class Service extends Context.Service<Service, Interface>()("@opencode/MarketplaceService") {}\n\nfunction clone<T>(value: T): T {\n  return structuredClone(value)\n}\n\nfunction publicSource(source: MarketplaceSource): MarketplaceSource {\n  const { headers: _headers, ...value } = source\n  return value\n}\n\nfunction publicState(state: MarketplaceState): MarketplaceState {\n  return {\n    revision: state.revision ?? 0,\n    ...(state.sources ? { sources: state.sources.map(publicSource) } : {}),\n    ...(state.installed\n      ? {\n          installed: Object.fromEntries(\n            Object.entries(state.installed).map(([key, installed]) => {\n              const {\n                materialized_plan: _materializedPlan,\n                active_plan: _activePlan,\n                artifact_digests: _artifactDigests,\n                catalog_digest: _catalogDigest,\n                manifest_digest: _manifestDigest,\n                materialized_digest: _materializedDigest,\n                ...value\n              } = installed\n              return [key, { ...value, receipt: {} }]\n            }),\n          ),\n        }\n      : {}),\n  }\n}\n\nfunction publicListing(listing: MarketplaceListing): MarketplaceListing {\n  return {\n    ...listing,\n    source: publicSource(listing.source),\n  }\n}\n\nfunction revisionFailure(expected: number, actual: number): MarketplaceMutationResult {\n  return {\n    ok: false,\n    reason: "revision",\n    message: `Marketplace state changed concurrently (expected revision ${expected}, actual ${actual})`,\n    revision: actual,\n  }\n}\n\nfunction notFound(message: string): MarketplaceMutationResult {\n  return { ok: false, reason: "not_found", message }\n}\n\nfunction stateWithout(state: MarketplaceState, key: string): MarketplaceState {\n  const installed = { ...(state.installed ?? {}) }\n  delete installed[key]\n  return {\n    ...clone(state),\n    installed,\n  }\n}\n\nfunction trusted(source: MarketplaceSource) {\n  return source.trust === "official" || source.trust === "verified"\n}\n\nfunction sourceHeaders(source: MarketplaceSource, target: string) {\n  if (!source.headers) return undefined\n  try {\n    return new URL(source.url).origin === new URL(target).origin ? source.headers : undefined\n  } catch {\n    return undefined\n  }\n}\n\nconst layer = Layer.effect(\n  Service,\n  Effect.gen(function* () {\n    const registry = yield* MarketplaceRegistry.Service\n    const cache = yield* MarketplaceCache.Service\n    const config = yield* Config.Service\n\n    const loadView = Effect.fnUntraced(function* (state: MarketplaceState, refresh: boolean) {\n      const loaded = yield* Effect.tryPromise({\n        try: () =>\n          loadMarketplace({\n            config: { marketplace: state },\n            fetch: cache.fetcher(refresh ? "refresh" : "cache-first"),\n          }),\n        catch: (error) => error,\n      }).pipe(Effect.orDie)\n      return {\n        state: publicState(state),\n        listings: loaded.listings.map(publicListing),\n        errors: loaded.errors.map((error) => ({ ...error, source: publicSource(error.source) })),\n        cache: yield* cache.summary(),\n      } satisfies MarketplaceView\n    })\n\n    const get = Effect.fn("MarketplaceService.get")(function* (options?: { refresh?: boolean }) {\n      return yield* loadView(yield* registry.read(), options?.refresh === true)\n    })\n\n    const rawBase = Effect.fnUntraced(function* () {\n      return (yield* config.getGlobalBase()) as MarketplaceHostConfig\n    })\n\n    const conflictList = Effect.fnUntraced(function* (\n      state: MarketplaceState,\n      listing: MarketplaceListing,\n    ) {\n      const base = yield* rawBase()\n      const effective = composeMarketplaceConfig(base, stateWithout(state, listing.key))\n      return marketplaceConflicts(effective, listing.item.install)\n    })\n\n    const plan = Effect.fn("MarketplaceService.plan")(function* (key: string) {\n      const state = yield* registry.read()\n      const view = yield* loadView(state, false)\n      const listing = view.listings.find((candidate) => candidate.key === key)\n      if (!listing) {\n        return {\n          ok: false,\n          reason: "not_found",\n          message: `Marketplace item not found: ${key}`,\n        } satisfies MarketplacePlanResult\n      }\n      const status = marketplaceStatus({ marketplace: state }, listing)\n      return {\n        ok: true,\n        key,\n        action: status === "update" ? "update" : "install",\n        trust_warning: !trusted(listing.source),\n        conflicts: yield* conflictList(state, listing),\n        permissions: marketplacePermissions(listing.item),\n        summary: marketplacePlanSummary(listing.item.install),\n      } satisfies MarketplacePlanResult\n    })\n\n    const findListing = Effect.fnUntraced(function* (state: MarketplaceState, key: string, refresh: boolean) {\n      const loaded = yield* Effect.tryPromise({\n        try: () =>\n          loadMarketplace({\n            config: { marketplace: state },\n            fetch: cache.fetcher(refresh ? "refresh" : "cache-first"),\n          }),\n        catch: (error) => error,\n      }).pipe(Effect.orDie)\n      return loaded.listings.find((listing) => listing.key === key)\n    })\n\n    const prepare = Effect.fnUntraced(function* (input: {\n      state: MarketplaceState\n      listing: MarketplaceListing\n      force?: boolean\n      acceptUntrusted?: boolean\n    }) {\n      const conflicts = yield* conflictList(input.state, input.listing)\n      if (conflicts.length && !input.force) {\n        return {\n          ok: false as const,\n          failure: {\n            ok: false,\n            reason: "conflict",\n            message: `Marketplace item conflicts with ${conflicts.map((item) => item.path).join(", ")}`,\n            revision: input.state.revision ?? 0,\n            conflicts,\n          } satisfies MarketplaceMutationResult,\n        }\n      }\n\n      if (!trusted(input.listing.source) && !input.acceptUntrusted) {\n        return {\n          ok: false as const,\n          failure: {\n            ok: false,\n            reason: "trust",\n            message: `Catalog ${input.listing.source.name} is marked ${input.listing.source.trust ?? "community"}`,\n            revision: input.state.revision ?? 0,\n          } satisfies MarketplaceMutationResult,\n        }\n      }\n\n      const materialized = yield* cache\n        .materializePlan(input.listing.item.install, input.listing.source)\n        .pipe(\n          Effect.map((value) => ({ ok: true as const, value })),\n          Effect.catch((error) =>\n            Effect.succeed({\n              ok: false as const,\n              failure: {\n                ok: false,\n                reason: "materialization",\n                message: error.message,\n                revision: input.state.revision ?? 0,\n              } satisfies MarketplaceMutationResult,\n            }),\n          ),\n        )\n      if (!materialized.ok) return materialized\n\n      const manifest = yield* cache\n        .putJson(\n          {\n            schema: "opencode.marketplace.manifest/v1",\n            source: {\n              id: input.listing.source.id,\n              name: input.listing.source.name,\n              url: input.listing.source.url,\n              trust: input.listing.source.trust,\n            },\n            catalog: {\n              id: input.listing.catalog.id,\n              name: input.listing.catalog.name,\n            },\n            item: input.listing.item,\n          },\n          { kind: "item-manifest", sourceUrl: input.listing.catalog_url ?? input.listing.source.url },\n        )\n        .pipe(\n          Effect.map((value) => ({ ok: true as const, value })),\n          Effect.catch((error) =>\n            Effect.succeed({\n              ok: false as const,\n              failure: {\n                ok: false,\n                reason: "materialization",\n                message: error.message,\n                revision: input.state.revision ?? 0,\n              } satisfies MarketplaceMutationResult,\n            }),\n          ),\n        )\n      if (!manifest.ok) return manifest\n\n      const artifactDigests = new Set(materialized.value.artifactDigests)\n      artifactDigests.add(manifest.value.digest)\n      if (input.listing.catalog_digest) artifactDigests.add(input.listing.catalog_digest)\n\n      for (const icon of Object.values(input.listing.item.icon ?? {})) {\n        if (!/^https?:\\/\\//i.test(icon)) continue\n        yield* cache\n          .fetchResponse({\n            url: icon,\n            headers: sourceHeaders(input.listing.source, icon),\n            kind: "icon",\n            mode: "refresh",\n          })\n          .pipe(\n            Effect.tap((response) =>\n              Effect.sync(() => {\n                const digest = response.headers.get("x-opencode-artifact-digest")\n                if (digest) artifactDigests.add(digest)\n              }),\n            ),\n            Effect.catch(() => Effect.void),\n          )\n      }\n\n      const current = input.state.installed?.[input.listing.key]\n      const components = marketplaceSkillComponents(input.listing.item.install)\n      const disabledSkills =\n        current?.disabled_skills?.filter((id) => components.some((component) => component.id === id)) ??\n        components.filter((component) => component.enabled === false).map((component) => component.id)\n      const disabledMcp =\n        current?.disabled_mcp?.filter((id) => id in (input.listing.item.install.mcp ?? {})) ??\n        marketplaceInitialDisabledMcp(input.listing.item.install)\n      const enabled = current?.enabled !== false\n      const activePlan = marketplaceActivePlan(materialized.value.plan, {\n        enabled,\n        disabled_skills: disabledSkills,\n        disabled_mcp: disabledMcp,\n      })\n      const now = new Date().toISOString()\n\n      const installed: MarketplaceInstalled = {\n        source: input.listing.source.id,\n        source_url: input.listing.source.reference ?? input.listing.source.url,\n        source_trust: input.listing.source.trust,\n        catalog: input.listing.catalog.id,\n        catalog_name: input.listing.catalog.name,\n        item: input.listing.item.id,\n        name: input.listing.item.name,\n        kind: input.listing.item.kind,\n        version: input.listing.item.version,\n        publisher: input.listing.item.publisher?.name ?? input.listing.catalog.publisher?.name,\n        fingerprint: marketplaceFingerprint(input.listing.item),\n        installed_at: current?.installed_at ?? now,\n        updated_at: now,\n        snapshot: marketplaceSnapshot(input.listing.item),\n        plan: clone(input.listing.item.install),\n        materialized_plan: materialized.value.plan,\n        active_plan: activePlan,\n        receipt: {},\n        enabled,\n        ...(disabledSkills.length ? { disabled_skills: disabledSkills } : {}),\n        ...(disabledMcp.length ? { disabled_mcp: disabledMcp } : {}),\n        ...(input.listing.catalog_digest ? { catalog_digest: input.listing.catalog_digest } : {}),\n        manifest_digest: manifest.value.digest,\n        ...(materialized.value.treeDigest ? { materialized_digest: materialized.value.treeDigest } : {}),\n        artifact_digests: Array.from(artifactDigests).toSorted(),\n      }\n\n      return { ok: true as const, installed }\n    })\n\n    const persist = Effect.fnUntraced(function* (input: {\n      state: MarketplaceState\n      connectMcp?: string[]\n      preserved?: string[]\n    }) {\n      const stored = yield* registry.replace(input.state).pipe(\n        Effect.map((value) => ({ ok: true as const, value })),\n        Effect.catch((error) => Effect.succeed({ ok: false as const, error })),\n      )\n      if (!stored.ok) {\n        const error = stored.error\n        if (error instanceof MarketplaceRegistry.ConflictError) return revisionFailure(error.expected, error.actual)\n        return revisionFailure(input.state.revision ?? 0, (yield* registry.read()).revision ?? 0)\n      }\n      if (stored.value.changed) yield* config.invalidate()\n      return {\n        ok: true,\n        changed: stored.value.changed,\n        view: yield* loadView(stored.value.state, false),\n        connect_mcp: Array.from(new Set(input.connectMcp ?? [])).toSorted(),\n        preserved: input.preserved ?? [],\n      } satisfies MarketplaceMutationResult\n    })\n\n    const install = Effect.fn("MarketplaceService.install")(function* (input: InstallInput) {\n      const state = yield* registry.read()\n      if ((state.revision ?? 0) !== input.expectedRevision) {\n        return revisionFailure(input.expectedRevision, state.revision ?? 0)\n      }\n      const listing = yield* findListing(state, input.key, true)\n      if (!listing) return notFound(`Marketplace item not found: ${input.key}`)\n      const prepared = yield* prepare({\n        state,\n        listing,\n        force: input.force,\n        acceptUntrusted: input.acceptUntrusted,\n      })\n      if (!prepared.ok) return prepared.failure\n      const next: MarketplaceState = {\n        ...clone(state),\n        installed: {\n          ...(state.installed ?? {}),\n          [listing.key]: prepared.installed,\n        },\n      }\n      return yield* persist({\n        state: next,\n        connectMcp: marketplaceEnabledMcpNames({ marketplace: { installed: { [listing.key]: prepared.installed } } }, listing.key),\n      })\n    })\n\n    const updateAll = Effect.fn("MarketplaceService.updateAll")(function* (input: UpdateAllInput) {\n      const state = yield* registry.read()\n      if ((state.revision ?? 0) !== input.expectedRevision) {\n        return revisionFailure(input.expectedRevision, state.revision ?? 0)\n      }\n      const loaded = yield* Effect.tryPromise({\n        try: () => loadMarketplace({ config: { marketplace: state }, fetch: cache.fetcher("refresh") }),\n        catch: (error) => error,\n      }).pipe(Effect.orDie)\n      const candidates = loaded.listings.filter(\n        (listing) => marketplaceStatus({ marketplace: state }, listing) === "update",\n      )\n      if (candidates.length === 0) {\n        return {\n          ok: true,\n          changed: false,\n          view: yield* loadView(state, false),\n          connect_mcp: [],\n          preserved: [],\n        } satisfies MarketplaceMutationResult\n      }\n\n      let working = clone(state)\n      const connect: string[] = []\n      for (const listing of candidates) {\n        const prepared = yield* prepare({\n          state: working,\n          listing,\n          force: input.force,\n          acceptUntrusted: input.acceptUntrusted,\n        })\n        if (!prepared.ok) return prepared.failure\n        working.installed = {\n          ...(working.installed ?? {}),\n          [listing.key]: prepared.installed,\n        }\n        connect.push(\n          ...marketplaceEnabledMcpNames(\n            { marketplace: { installed: { [listing.key]: prepared.installed } } },\n            listing.key,\n          ),\n        )\n      }\n      return yield* persist({ state: working, connectMcp: connect })\n    })\n\n    const uninstall = Effect.fn("MarketplaceService.uninstall")(function* (input: {\n      key: string\n      expectedRevision: number\n    }) {\n      const state = yield* registry.read()\n      if ((state.revision ?? 0) !== input.expectedRevision) {\n        return revisionFailure(input.expectedRevision, state.revision ?? 0)\n      }\n      if (!state.installed?.[input.key]) return notFound(`Marketplace install not found: ${input.key}`)\n      const installed = { ...state.installed }\n      delete installed[input.key]\n      return yield* persist({\n        state: {\n          ...clone(state),\n          installed,\n        },\n      })\n    })\n\n    const toggle = Effect.fn("MarketplaceService.toggle")(function* (input: ToggleInput) {\n      const state = yield* registry.read()\n      if ((state.revision ?? 0) !== input.expectedRevision) {\n        return revisionFailure(input.expectedRevision, state.revision ?? 0)\n      }\n      const current = state.installed?.[input.key]\n      if (!current) return notFound(`Marketplace install not found: ${input.key}`)\n\n      const next = clone(current)\n      if (input.component === "package") {\n        next.enabled = input.enabled\n      } else if (input.component === "skill") {\n        if (!input.id || !marketplaceSkillComponents(next.plan).some((component) => component.id === input.id)) {\n          return notFound(`Marketplace skill not found: ${input.id ?? ""}`)\n        }\n        next.disabled_skills = input.enabled\n          ? (next.disabled_skills ?? []).filter((id) => id !== input.id)\n          : Array.from(new Set([...(next.disabled_skills ?? []), input.id]))\n      } else {\n        if (!input.id || !(input.id in (next.plan.mcp ?? {}))) {\n          return notFound(`Marketplace MCP server not found: ${input.id ?? ""}`)\n        }\n        next.disabled_mcp = input.enabled\n          ? (next.disabled_mcp ?? []).filter((id) => id !== input.id)\n          : Array.from(new Set([...(next.disabled_mcp ?? []), input.id]))\n      }\n\n      if (!next.disabled_skills?.length) delete next.disabled_skills\n      if (!next.disabled_mcp?.length) delete next.disabled_mcp\n      next.active_plan = marketplaceActivePlan(next.materialized_plan ?? next.plan, next)\n      next.updated_at = new Date().toISOString()\n\n      const nextState: MarketplaceState = {\n        ...clone(state),\n        installed: {\n          ...state.installed,\n          [input.key]: next,\n        },\n      }\n      return yield* persist({\n        state: nextState,\n        connectMcp: marketplaceEnabledMcpNames({ marketplace: { installed: { [input.key]: next } } }, input.key),\n      })\n    })\n\n    const sourceAdd = Effect.fn("MarketplaceService.sourceAdd")(function* (input: SourceAddInput) {\n      const state = yield* registry.read()\n      if ((state.revision ?? 0) !== input.expectedRevision) {\n        return revisionFailure(input.expectedRevision, state.revision ?? 0)\n      }\n      const source = createMarketplaceSource({\n        url: input.url,\n        name: input.name,\n        trust: input.trust,\n        headers: input.headers,\n      })\n      const next = upsertMarketplaceSource({ marketplace: state }, source).marketplace ?? state\n      return yield* persist({ state: next })\n    })\n\n    const sourceToggle = Effect.fn("MarketplaceService.sourceToggle")(function* (input: {\n      id: string\n      expectedRevision: number\n      enabled: boolean\n    }) {\n      const state = yield* registry.read()\n      if ((state.revision ?? 0) !== input.expectedRevision) {\n        return revisionFailure(input.expectedRevision, state.revision ?? 0)\n      }\n      const next = toggleMarketplaceSource({ marketplace: state }, input.id, input.enabled).marketplace ?? state\n      return yield* persist({ state: next })\n    })\n\n    const sourceRemove = Effect.fn("MarketplaceService.sourceRemove")(function* (input: {\n      id: string\n      expectedRevision: number\n    }) {\n      const state = yield* registry.read()\n      if ((state.revision ?? 0) !== input.expectedRevision) {\n        return revisionFailure(input.expectedRevision, state.revision ?? 0)\n      }\n      const next = removeMarketplaceSource({ marketplace: state }, input.id).marketplace ?? state\n      return yield* persist({ state: next })\n    })\n\n    const profileExport = Effect.fn("MarketplaceService.profileExport")(function* (input?: {\n      name?: string\n      description?: string\n    }) {\n      return exportMarketplaceProfile(yield* registry.read(), input)\n    })\n\n    const cachePrune = Effect.fn("MarketplaceService.cachePrune")(function* (input?: { maxAgeDays?: number }) {\n      const state = yield* registry.read()\n      const keep = new Set<string>()\n      for (const installed of Object.values(state.installed ?? {})) {\n        for (const digest of installed.artifact_digests ?? []) keep.add(digest)\n        if (installed.catalog_digest) keep.add(installed.catalog_digest)\n        if (installed.manifest_digest) keep.add(installed.manifest_digest)\n        if (installed.materialized_digest) keep.add(installed.materialized_digest)\n      }\n      return (yield* cache.prune({ keep, maxAgeDays: input?.maxAgeDays }).pipe(Effect.orDie)).summary\n    })\n\n    return Service.of({\n      get,\n      plan,\n      install,\n      updateAll,\n      uninstall,\n      toggle,\n      sourceAdd,\n      sourceToggle,\n      sourceRemove,\n      profileExport,\n      cachePrune,\n    })\n  }),\n)\n\nexport const node = LayerNode.make({\n  service: Service,\n  layer,\n  deps: [Config.node, MarketplaceCache.node, MarketplaceRegistry.node],\n})\n')

write('packages/opencode/src/server/routes/instance/httpapi/groups/marketplace.ts', 'import { Schema } from "effect"\nimport { MarketplaceSchema } from "@opencode-ai/core/marketplace-schema"\nimport { HttpApi, HttpApiEndpoint, HttpApiGroup, OpenApi } from "effect/unstable/httpapi"\nimport { described } from "./metadata"\n\nconst root = "/marketplace"\n\nexport const MarketplacePaths = {\n  get: root,\n  refresh: `${root}/refresh`,\n  plan: `${root}/plan`,\n  install: `${root}/install`,\n  updateAll: `${root}/update-all`,\n  installed: `${root}/install/:key`,\n  source: `${root}/source`,\n  sourceItem: `${root}/source/:id`,\n  profile: `${root}/profile`,\n  cachePrune: `${root}/cache/prune`,\n} as const\n\nexport const MarketplaceApi = HttpApi.make("marketplace").add(\n  HttpApiGroup.make("marketplace")\n    .add(\n      HttpApiEndpoint.get("get", MarketplacePaths.get, {\n        success: described(MarketplaceSchema.View, "Marketplace state and catalog"),\n      }).annotateMerge(\n        OpenApi.annotations({\n          identifier: "marketplace.get",\n          summary: "Get Marketplace",\n          description: "Get local Marketplace state, cached catalogs, and cache statistics.",\n        }),\n      ),\n      HttpApiEndpoint.post("refresh", MarketplacePaths.refresh, {\n        success: described(MarketplaceSchema.View, "Refreshed Marketplace"),\n      }).annotateMerge(\n        OpenApi.annotations({\n          identifier: "marketplace.refresh",\n          summary: "Refresh Marketplace",\n          description: "Revalidate enabled catalog sources and return the current Marketplace view.",\n        }),\n      ),\n      HttpApiEndpoint.post("plan", MarketplacePaths.plan, {\n        payload: MarketplaceSchema.PlanInput,\n        success: described(MarketplaceSchema.PlanResult, "Marketplace install plan"),\n      }).annotateMerge(\n        OpenApi.annotations({\n          identifier: "marketplace.plan",\n          summary: "Plan Marketplace install",\n          description: "Preview trust requirements, permissions, and configuration conflicts.",\n        }),\n      ),\n      HttpApiEndpoint.post("install", MarketplacePaths.install, {\n        payload: MarketplaceSchema.InstallInput,\n        success: described(MarketplaceSchema.MutationResult, "Marketplace install result"),\n      }).annotateMerge(\n        OpenApi.annotations({\n          identifier: "marketplace.install",\n          summary: "Install Marketplace item",\n          description: "Materialize and install a Marketplace item using revision-based concurrency control.",\n        }),\n      ),\n      HttpApiEndpoint.post("updateAll", MarketplacePaths.updateAll, {\n        payload: MarketplaceSchema.UpdateAllInput,\n        success: described(MarketplaceSchema.MutationResult, "Marketplace update result"),\n      }).annotateMerge(\n        OpenApi.annotations({\n          identifier: "marketplace.updateAll",\n          summary: "Update Marketplace items",\n          description: "Atomically update all available Marketplace items.",\n        }),\n      ),\n      HttpApiEndpoint.delete("uninstall", MarketplacePaths.installed, {\n        params: { key: Schema.String },\n        payload: MarketplaceSchema.RevisionInput,\n        success: described(MarketplaceSchema.MutationResult, "Marketplace uninstall result"),\n      }).annotateMerge(\n        OpenApi.annotations({\n          identifier: "marketplace.uninstall",\n          summary: "Uninstall Marketplace item",\n          description: "Remove an installed Marketplace item without rewriting user configuration.",\n        }),\n      ),\n      HttpApiEndpoint.patch("toggle", MarketplacePaths.installed, {\n        params: { key: Schema.String },\n        payload: MarketplaceSchema.ToggleInput,\n        success: described(MarketplaceSchema.MutationResult, "Marketplace component toggle result"),\n      }).annotateMerge(\n        OpenApi.annotations({\n          identifier: "marketplace.toggle",\n          summary: "Toggle Marketplace component",\n          description: "Enable or disable a package, skill, or MCP server.",\n        }),\n      ),\n      HttpApiEndpoint.post("sourceAdd", MarketplacePaths.source, {\n        payload: MarketplaceSchema.SourceAddInput,\n        success: described(MarketplaceSchema.MutationResult, "Marketplace source result"),\n      }).annotateMerge(\n        OpenApi.annotations({\n          identifier: "marketplace.sourceAdd",\n          summary: "Add Marketplace source",\n          description: "Add or replace a Marketplace catalog source.",\n        }),\n      ),\n      HttpApiEndpoint.patch("sourceToggle", MarketplacePaths.sourceItem, {\n        params: { id: Schema.String },\n        payload: MarketplaceSchema.SourceToggleInput,\n        success: described(MarketplaceSchema.MutationResult, "Marketplace source result"),\n      }).annotateMerge(\n        OpenApi.annotations({\n          identifier: "marketplace.sourceToggle",\n          summary: "Toggle Marketplace source",\n          description: "Enable or disable a Marketplace catalog source.",\n        }),\n      ),\n      HttpApiEndpoint.delete("sourceRemove", MarketplacePaths.sourceItem, {\n        params: { id: Schema.String },\n        payload: MarketplaceSchema.RevisionInput,\n        success: described(MarketplaceSchema.MutationResult, "Marketplace source result"),\n      }).annotateMerge(\n        OpenApi.annotations({\n          identifier: "marketplace.sourceRemove",\n          summary: "Remove Marketplace source",\n          description: "Remove a source while keeping installed packages manageable.",\n        }),\n      ),\n      HttpApiEndpoint.post("profileExport", MarketplacePaths.profile, {\n        payload: MarketplaceSchema.ProfileExportInput,\n        success: described(MarketplaceSchema.Profile, "Portable Marketplace profile"),\n      }).annotateMerge(\n        OpenApi.annotations({\n          identifier: "marketplace.profileExport",\n          summary: "Export Marketplace profile",\n          description: "Export a deterministic profile without credentials or local cache paths.",\n        }),\n      ),\n      HttpApiEndpoint.post("cachePrune", MarketplacePaths.cachePrune, {\n        payload: MarketplaceSchema.CachePruneInput,\n        success: described(MarketplaceSchema.CacheSummary, "Marketplace cache summary"),\n      }).annotateMerge(\n        OpenApi.annotations({\n          identifier: "marketplace.cachePrune",\n          summary: "Prune Marketplace cache",\n          description: "Remove stale unreferenced content-addressed artifacts.",\n        }),\n      ),\n    )\n    .annotateMerge(\n      OpenApi.annotations({\n        title: "marketplace",\n        description: "Marketplace catalogs, installations, component state, profiles, and artifact cache.",\n      }),\n    ),\n)\n')

write('packages/opencode/src/server/routes/instance/httpapi/handlers/marketplace.ts', 'import { Effect } from "effect"\nimport { HttpApiBuilder } from "effect/unstable/httpapi"\nimport { EffectBridge } from "@/effect/bridge"\nimport { disposeAllInstancesAndEmitGlobalDisposed } from "@/server/global-lifecycle"\nimport { RootHttpApi } from "../api"\nimport { Service as MarketplaceService } from "@/marketplace/service"\n\nexport const marketplaceHandlers = HttpApiBuilder.group(RootHttpApi, "marketplace", (handlers) =>\n  Effect.gen(function* () {\n    const marketplace = yield* MarketplaceService\n    const bridge = yield* EffectBridge.make()\n\n    const runtime = <T extends { ok: boolean; changed?: boolean }>(result: T) => {\n      if (result.ok && result.changed) {\n        bridge.fork(disposeAllInstancesAndEmitGlobalDisposed({ swallowErrors: true }))\n      }\n      return result\n    }\n\n    return handlers\n      .handle("get", () => marketplace.get())\n      .handle("refresh", () => marketplace.get({ refresh: true }))\n      .handle("plan", (ctx) => marketplace.plan(ctx.payload.key))\n      .handle("install", (ctx) =>\n        marketplace\n          .install({\n            key: ctx.payload.key,\n            expectedRevision: ctx.payload.expected_revision,\n            force: ctx.payload.force,\n            acceptUntrusted: ctx.payload.accept_untrusted,\n          })\n          .pipe(Effect.map(runtime)),\n      )\n      .handle("updateAll", (ctx) =>\n        marketplace\n          .updateAll({\n            expectedRevision: ctx.payload.expected_revision,\n            force: ctx.payload.force,\n            acceptUntrusted: ctx.payload.accept_untrusted,\n          })\n          .pipe(Effect.map(runtime)),\n      )\n      .handle("uninstall", (ctx) =>\n        marketplace\n          .uninstall({\n            key: ctx.params.key,\n            expectedRevision: ctx.payload.expected_revision,\n          })\n          .pipe(Effect.map(runtime)),\n      )\n      .handle("toggle", (ctx) =>\n        marketplace\n          .toggle({\n            key: ctx.params.key,\n            expectedRevision: ctx.payload.expected_revision,\n            component: ctx.payload.component,\n            id: ctx.payload.id,\n            enabled: ctx.payload.enabled,\n          })\n          .pipe(Effect.map(runtime)),\n      )\n      .handle("sourceAdd", (ctx) =>\n        marketplace.sourceAdd({\n          expectedRevision: ctx.payload.expected_revision,\n          url: ctx.payload.url,\n          name: ctx.payload.name,\n          trust: ctx.payload.trust,\n          headers: ctx.payload.headers,\n        }),\n      )\n      .handle("sourceToggle", (ctx) =>\n        marketplace.sourceToggle({\n          id: ctx.params.id,\n          expectedRevision: ctx.payload.expected_revision,\n          enabled: ctx.payload.enabled,\n        }),\n      )\n      .handle("sourceRemove", (ctx) =>\n        marketplace.sourceRemove({\n          id: ctx.params.id,\n          expectedRevision: ctx.payload.expected_revision,\n        }),\n      )\n      .handle("profileExport", (ctx) =>\n        marketplace.profileExport({\n          name: ctx.payload.name,\n          description: ctx.payload.description,\n        }),\n      )\n      .handle("cachePrune", (ctx) =>\n        marketplace.cachePrune({\n          maxAgeDays: ctx.payload.max_age_days,\n        }),\n      )\n  }),\n)\n')

write('packages/app/src/components/marketplace-dialog.tsx', 'import {\n  OFFICIAL_MARKETPLACE_SOURCE,\n  marketplaceItemEnabled,\n  marketplaceMcpEnabled,\n  marketplacePermissions,\n  marketplacePlanSummary,\n  marketplaceSkillComponents,\n  marketplaceSkillEnabled,\n  marketplaceSources,\n  marketplaceStatus,\n  type MarketplaceConfiguredTrust,\n  type MarketplaceConflict,\n  type MarketplaceHostConfig,\n  type MarketplaceListing,\n  type MarketplaceMutationResult,\n  type MarketplacePlanResult,\n  type MarketplaceSource,\n  type MarketplaceView,\n} from "@opencode-ai/core/marketplace"\nimport { Dialog } from "@opencode-ai/ui/dialog"\nimport { Switch } from "@opencode-ai/ui/switch"\nimport { useLanguage } from "@/context/language"\nimport { useServerSync } from "@/context/server-sync"\nimport { showToast } from "@/utils/toast"\nimport { createEffect, createMemo, createResource, createSignal, For, Show } from "solid-js"\nimport { createStore } from "solid-js/store"\n\nconst TABS = ["discover", "installed", "updates", "sources"] as const\nconst KINDS = ["all", "plugin", "skill", "agent", "command", "mcp", "bundle"] as const\n\ntype Tab = (typeof TABS)[number]\ntype KindFilter = (typeof KINDS)[number]\ntype PendingAction = "install" | "update" | "uninstall"\n\ntype Pending = {\n  listing: MarketplaceListing\n  action: PendingAction\n  conflicts: MarketplaceConflict[]\n  trustWarning: boolean\n}\n\nexport function DialogMarketplace() {\n  return (\n    <Dialog\n      size="x-large"\n      class="!h-[min(760px,calc(100vh-32px))] !w-[min(1180px,calc(100vw-32px))]"\n      title="Marketplace"\n      description="Discover and manage OpenCode extensions from local, content-addressed catalogs."\n    >\n      <MarketplacePanel />\n    </Dialog>\n  )\n}\n\nexport function MarketplacePanel() {\n  const sync = useServerSync()\n  const language = useLanguage()\n  const [view, actions] = createResource(async () => (await sync().marketplace.get()) as MarketplaceView)\n  const [store, setStore] = createStore({\n    tab: "discover" as Tab,\n    kind: "all" as KindFilter,\n    query: "",\n    selected: undefined as string | undefined,\n    busy: false,\n    pending: undefined as Pending | undefined,\n    sourceURL: "",\n    sourceName: "",\n    sourceTrust: "community" as MarketplaceConfiguredTrust,\n  })\n\n  const state = () => view()?.state ?? { revision: 0 }\n  const config = () => ({ marketplace: state() }) satisfies MarketplaceHostConfig\n  const revision = () => state().revision ?? 0\n  const listings = () => view()?.listings ?? []\n  const status = (listing: MarketplaceListing) => marketplaceStatus(config(), listing)\n  const updates = createMemo(() => listings().filter((listing) => status(listing) === "update"))\n  const visible = createMemo(() => {\n    const query = store.query.trim().toLowerCase()\n    return listings().filter((listing) => {\n      const value = status(listing)\n      if (store.tab === "discover" && listing.orphaned) return false\n      if (store.tab === "installed" && value === "available") return false\n      if (store.tab === "updates" && value !== "update") return false\n      if (store.kind !== "all" && listing.item.kind !== store.kind) return false\n      if (!query) return true\n      return [\n        listing.item.name,\n        listing.item.description,\n        listing.item.publisher?.name,\n        listing.catalog.name,\n        listing.source.name,\n        listing.item.kind,\n        ...(listing.item.tags ?? []),\n      ]\n        .filter((item): item is string => Boolean(item))\n        .join(" ")\n        .toLowerCase()\n        .includes(query)\n    })\n  })\n  const current = createMemo(() => visible().find((listing) => listing.key === store.selected) ?? visible()[0])\n\n  createEffect(() => {\n    const listing = current()\n    if (listing && listing.key !== store.selected) setStore("selected", listing.key)\n  })\n\n  async function run(\n    request: Promise<MarketplaceMutationResult>,\n    message: string,\n    options?: { restorePending?: Pending },\n  ) {\n    setStore("busy", true)\n    try {\n      const result = await request\n      if (!result.ok) {\n        showToast({\n          variant: "error",\n          title: "Marketplace request failed",\n          description: result.message,\n        })\n        if (options?.restorePending) setStore("pending", options.restorePending)\n        return false\n      }\n      actions.mutate(result.view)\n      await Promise.allSettled(\n        result.connect_mcp.map((name) => sync().mcp.connect(sync().data.path.directory, name)),\n      )\n      showToast({ variant: "success", description: message })\n      if (result.preserved.length) {\n        showToast({\n          title: "Settings preserved",\n          description: result.preserved.join(", "),\n        })\n      }\n      return true\n    } catch (error) {\n      showToast({\n        variant: "error",\n        title: "Marketplace request failed",\n        description: error instanceof Error ? error.message : String(error),\n      })\n      if (options?.restorePending) setStore("pending", options.restorePending)\n      return false\n    } finally {\n      setStore("busy", false)\n    }\n  }\n\n  async function refresh() {\n    setStore("busy", true)\n    try {\n      actions.mutate((await sync().marketplace.refresh()) as MarketplaceView)\n    } catch (error) {\n      showToast({\n        variant: "error",\n        title: "Marketplace refresh failed",\n        description: error instanceof Error ? error.message : String(error),\n      })\n    } finally {\n      setStore("busy", false)\n    }\n  }\n\n  async function request(listing: MarketplaceListing) {\n    const value = status(listing)\n    if (value === "installed") {\n      setStore("pending", { listing, action: "uninstall", conflicts: [], trustWarning: false })\n      return\n    }\n    setStore("busy", true)\n    try {\n      const result = (await sync().marketplace.plan({ key: listing.key })) as MarketplacePlanResult\n      if (!result.ok) {\n        showToast({ variant: "error", title: "Marketplace plan failed", description: result.message })\n        return\n      }\n      setStore("pending", {\n        listing,\n        action: result.action,\n        conflicts: result.conflicts,\n        trustWarning: result.trust_warning,\n      })\n    } catch (error) {\n      showToast({\n        variant: "error",\n        title: "Marketplace plan failed",\n        description: error instanceof Error ? error.message : String(error),\n      })\n    } finally {\n      setStore("busy", false)\n    }\n  }\n\n  async function confirm() {\n    const pending = store.pending\n    if (!pending) return\n    setStore("pending", undefined)\n    if (pending.action === "uninstall") {\n      await run(\n        sync().marketplace.uninstall({\n          key: pending.listing.key,\n          expected_revision: revision(),\n        }) as Promise<MarketplaceMutationResult>,\n        `Removed ${pending.listing.item.name}`,\n        { restorePending: pending },\n      )\n      return\n    }\n    await run(\n      sync().marketplace.install({\n        key: pending.listing.key,\n        expected_revision: revision(),\n        force: pending.conflicts.length > 0,\n        accept_untrusted: pending.trustWarning,\n      }) as Promise<MarketplaceMutationResult>,\n      `${pending.action === "update" ? "Updated" : "Installed"} ${pending.listing.item.name}`,\n      { restorePending: pending },\n    )\n  }\n\n  async function updateAll() {\n    await run(\n      sync().marketplace.updateAll({\n        expected_revision: revision(),\n        force: false,\n        accept_untrusted: false,\n      }) as Promise<MarketplaceMutationResult>,\n      `Updated ${updates().length} Marketplace item${updates().length === 1 ? "" : "s"}`,\n    )\n  }\n\n  async function addSource() {\n    const url = store.sourceURL.trim()\n    if (!url) return\n    const success = await run(\n      sync().marketplace.sourceAdd({\n        expected_revision: revision(),\n        url,\n        name: store.sourceName.trim() || undefined,\n        trust: store.sourceTrust,\n      }) as Promise<MarketplaceMutationResult>,\n      "Marketplace source added",\n    )\n    if (success) setStore({ sourceURL: "", sourceName: "", sourceTrust: "community" })\n  }\n\n  async function prune() {\n    setStore("busy", true)\n    try {\n      const summary = await sync().marketplace.cachePrune({ max_age_days: 30 })\n      const current = view()\n      if (current) actions.mutate({ ...current, cache: summary })\n      showToast({\n        variant: "success",\n        description: `Marketplace cache pruned: ${summary.objects} objects remain`,\n      })\n    } catch (error) {\n      showToast({\n        variant: "error",\n        title: "Marketplace cache prune failed",\n        description: error instanceof Error ? error.message : String(error),\n      })\n    } finally {\n      setStore("busy", false)\n    }\n  }\n\n  return (\n    <div class="relative flex h-full min-h-0 flex-col gap-3 overflow-hidden p-3">\n      <div class="flex flex-wrap items-start justify-between gap-3">\n        <div>\n          <h2 class="text-16-medium text-text-strong">Marketplace</h2>\n          <p class="mt-1 text-12-regular text-text-weak">\n            SQLite registry · content-addressed cache · revision {revision()}\n          </p>\n        </div>\n        <div class="flex flex-wrap items-center gap-2 text-12-regular text-text-weak">\n          <span>{Object.keys(state().installed ?? {}).length} installed</span>\n          <Show when={view()?.cache}>\n            {(cache) => (\n              <span>\n                {cache().objects} cached · {formatBytes(cache().total_bytes)}\n              </span>\n            )}\n          </Show>\n          <Show when={updates().length}>\n            <button\n              type="button"\n              disabled={store.busy}\n              class="rounded-md bg-surface-raised-base px-2 py-1 text-text-strong hover:bg-surface-raised-base-hover disabled:opacity-50"\n              onClick={() => void updateAll()}\n            >\n              Update all ({updates().length})\n            </button>\n          </Show>\n          <button\n            type="button"\n            disabled={store.busy}\n            class="rounded-md border border-border-base px-2 py-1 text-text-base hover:bg-surface-raised-base-hover disabled:opacity-50"\n            onClick={() => void prune()}\n          >\n            Prune cache\n          </button>\n          <button\n            type="button"\n            disabled={store.busy}\n            class="rounded-md border border-border-base px-2 py-1 text-text-base hover:bg-surface-raised-base-hover disabled:opacity-50"\n            onClick={() => void refresh()}\n          >\n            Refresh\n          </button>\n        </div>\n      </div>\n\n      <div class="flex flex-wrap items-center gap-1 border-b border-border-weak pb-2">\n        <For each={TABS}>\n          {(tab) => (\n            <button\n              type="button"\n              class="rounded-md px-2.5 py-1.5 text-12-medium capitalize"\n              classList={{\n                "bg-surface-raised-base text-text-strong": store.tab === tab,\n                "text-text-weak hover:text-text-base": store.tab !== tab,\n              }}\n              onClick={() => setStore("tab", tab)}\n            >\n              {tab}\n              <Show when={tab === "updates" && updates().length}> ({updates().length})</Show>\n            </button>\n          )}\n        </For>\n      </div>\n\n      <Show\n        when={store.tab === "sources"}\n        fallback={\n          <div class="flex min-h-0 flex-1 gap-3 overflow-hidden">\n            <div class="flex min-h-0 w-[42%] min-w-72 flex-col overflow-hidden rounded-lg border border-border-weak bg-surface-base">\n              <div class="flex gap-2 border-b border-border-weak p-2">\n                <input\n                  autofocus\n                  value={store.query}\n                  onInput={(event) => setStore("query", event.currentTarget.value)}\n                  placeholder="Search marketplace"\n                  class="min-w-0 flex-1 rounded-md border border-border-base bg-background-base px-2.5 py-1.5 text-13-regular text-text-strong outline-none focus:border-border-strong"\n                />\n                <select\n                  value={store.kind}\n                  onChange={(event) => setStore("kind", event.currentTarget.value as KindFilter)}\n                  class="rounded-md border border-border-base bg-background-base px-2 text-12-regular text-text-base"\n                >\n                  <For each={KINDS}>{(kind) => <option value={kind}>{kind}</option>}</For>\n                </select>\n              </div>\n              <div class="min-h-0 flex-1 overflow-y-auto p-1.5">\n                <Show\n                  when={!view.loading}\n                  fallback={<div class="p-6 text-center text-13-regular text-text-weak">Loading catalogs…</div>}\n                >\n                  <Show\n                    when={visible().length}\n                    fallback={<div class="p-6 text-center text-13-regular text-text-weak">No matching items.</div>}\n                  >\n                    <For each={visible()}>\n                      {(listing) => (\n                        <button\n                          type="button"\n                          class="mb-1 flex w-full gap-2.5 rounded-md px-2.5 py-2 text-left hover:bg-surface-raised-base-hover"\n                          classList={{ "bg-surface-raised-base": current()?.key === listing.key }}\n                          onClick={() => setStore("selected", listing.key)}\n                        >\n                          <PluginIcon listing={listing} />\n                          <div class="min-w-0 flex-1">\n                            <div class="flex items-center justify-between gap-2">\n                              <span class="truncate text-13-medium text-text-strong">{listing.item.name}</span>\n                              <Status value={status(listing)} />\n                            </div>\n                            <div class="mt-1 line-clamp-2 text-12-regular text-text-weak">\n                              {listing.item.description}\n                            </div>\n                            <div class="mt-1 flex gap-2 text-11-regular text-text-weak">\n                              <span class="capitalize">{listing.item.kind}</span>\n                              <span>v{listing.item.version}</span>\n                              <span class="truncate">{listing.source.name}</span>\n                            </div>\n                          </div>\n                        </button>\n                      )}\n                    </For>\n                  </Show>\n                </Show>\n              </div>\n            </div>\n            <div class="min-h-0 min-w-0 flex-1 overflow-y-auto rounded-lg border border-border-weak bg-surface-base p-4">\n              <Show\n                when={current()}\n                fallback={\n                  <div class="flex h-full items-center justify-center text-13-regular text-text-weak">\n                    Select an item.\n                  </div>\n                }\n              >\n                {(listing) => (\n                  <Details\n                    listing={listing()}\n                    config={config()}\n                    busy={store.busy}\n                    action={() => void request(listing())}\n                    toggle={(component, id, enabled, label) =>\n                      void run(\n                        sync().marketplace.toggle({\n                          key: listing().key,\n                          expected_revision: revision(),\n                          component,\n                          id,\n                          enabled,\n                        }) as Promise<MarketplaceMutationResult>,\n                        label,\n                      )\n                    }\n                  />\n                )}\n              </Show>\n            </div>\n          </div>\n        }\n      >\n        <Sources\n          sources={marketplaceSources(config())}\n          errors={view()?.errors ?? []}\n          busy={store.busy}\n          sourceURL={store.sourceURL}\n          sourceName={store.sourceName}\n          sourceTrust={store.sourceTrust}\n          setURL={(value) => setStore("sourceURL", value)}\n          setName={(value) => setStore("sourceName", value)}\n          setTrust={(value) => setStore("sourceTrust", value)}\n          add={() => void addSource()}\n          toggle={(source) =>\n            void run(\n              sync().marketplace.sourceToggle({\n                id: source.id,\n                expected_revision: revision(),\n                enabled: source.enabled === false,\n              }) as Promise<MarketplaceMutationResult>,\n              `${source.enabled === false ? "Enabled" : "Disabled"} ${source.name}`,\n            )\n          }\n          remove={(source) =>\n            void run(\n              sync().marketplace.sourceRemove({\n                id: source.id,\n                expected_revision: revision(),\n              }) as Promise<MarketplaceMutationResult>,\n              `Removed ${source.name}`,\n            )\n          }\n        />\n      </Show>\n\n      <Show when={store.pending}>\n        {(pending) => (\n          <div class="absolute inset-0 z-10 flex items-center justify-center bg-background-base/80 p-4">\n            <div class="w-full max-w-lg rounded-xl border border-border-base bg-surface-base p-4 shadow-lg">\n              <h3 class="text-15-medium text-text-strong capitalize">\n                {pending().action} {pending().listing.item.name}\n              </h3>\n              <p class="mt-2 text-12-regular text-text-weak">\n                {pending().action === "uninstall"\n                  ? "The SQLite installation record will be removed. User configuration is not rewritten."\n                  : marketplacePlanSummary(pending().listing.item.install)}\n              </p>\n              <Show when={pending().trustWarning}>\n                <div class="mt-3 rounded-md border border-border-warning px-3 py-2 text-12-regular text-text-base">\n                  This catalog is marked {pending().listing.source.trust ?? "community"}. Confirm to allow its code\n                  and remote assets.\n                </div>\n              </Show>\n              <Show when={pending().conflicts.length}>\n                <div class="mt-3 rounded-md border border-border-warning px-3 py-2 text-12-regular text-text-base">\n                  <div class="font-medium">These settings will be shadowed:</div>\n                  <For each={pending().conflicts}>\n                    {(conflict) => <div class="mt-1 font-mono">{conflict.path}</div>}\n                  </For>\n                </div>\n              </Show>\n              <Show when={pending().action !== "uninstall" && marketplacePermissions(pending().listing.item).length}>\n                <div class="mt-3 text-12-regular text-text-weak">\n                  <div class="font-medium text-text-base">Requested capabilities</div>\n                  <For each={marketplacePermissions(pending().listing.item)}>\n                    {(permission) => <div class="mt-1">• {permission}</div>}\n                  </For>\n                </div>\n              </Show>\n              <div class="mt-4 flex justify-end gap-2">\n                <button\n                  type="button"\n                  class="rounded-md px-3 py-1.5 text-12-medium text-text-base hover:bg-surface-raised-base-hover"\n                  onClick={() => setStore("pending", undefined)}\n                >\n                  Cancel\n                </button>\n                <button\n                  type="button"\n                  disabled={store.busy}\n                  class="rounded-md bg-surface-raised-base px-3 py-1.5 text-12-medium text-text-strong hover:bg-surface-raised-base-hover disabled:opacity-50"\n                  onClick={() => void confirm()}\n                >\n                  Confirm\n                </button>\n              </div>\n            </div>\n          </div>\n        )}\n      </Show>\n    </div>\n  )\n}\n\nfunction Status(props: { value: ReturnType<typeof marketplaceStatus> }) {\n  return <span class="shrink-0 rounded bg-surface-raised-base px-1.5 py-0.5 text-10-medium uppercase">{props.value}</span>\n}\n\nfunction PluginIcon(props: { listing: MarketplaceListing }) {\n  const [failed, setFailed] = createSignal(false)\n  const src = () => props.listing.item.icon?.["src-light"]\n  const initials = () =>\n    props.listing.item.name\n      .split(/\\s+/)\n      .slice(0, 2)\n      .map((part) => part[0])\n      .join("")\n      .toUpperCase()\n  return (\n    <div\n      class="flex size-10 shrink-0 items-center justify-center overflow-hidden rounded-xl text-12-medium text-white shadow-sm"\n      style={{ "background-color": props.listing.item.brand_color ?? "#5C6470" }}\n    >\n      <Show when={src() && !failed()} fallback={<span aria-hidden="true">{initials()}</span>}>\n        <img\n          src={src()}\n          alt=""\n          loading="lazy"\n          referrerpolicy="no-referrer"\n          class="size-full object-cover"\n          onError={() => setFailed(true)}\n        />\n      </Show>\n    </div>\n  )\n}\n\nfunction Details(props: {\n  listing: MarketplaceListing\n  config: MarketplaceHostConfig\n  busy: boolean\n  action: () => void\n  toggle: (component: "package" | "skill" | "mcp", id: string | undefined, enabled: boolean, label: string) => void\n}) {\n  const language = useLanguage()\n  const status = () => marketplaceStatus(props.config, props.listing)\n  const installed = () => props.config.marketplace?.installed?.[props.listing.key]\n  const enabled = () => marketplaceItemEnabled(props.config, props.listing.key)\n  const skills = () => marketplaceSkillComponents(installed()?.plan ?? props.listing.item.install)\n  const mcp = () => Object.keys(installed()?.plan.mcp ?? props.listing.item.install.mcp ?? {})\n\n  return (\n    <div class="flex min-h-full flex-col">\n      <div class="flex items-start justify-between gap-4">\n        <div class="min-w-0">\n          <div class="flex flex-wrap items-center gap-2">\n            <h3 class="text-18-medium text-text-strong">{props.listing.item.name}</h3>\n            <Status value={status()} />\n          </div>\n          <div class="mt-1 text-12-regular text-text-weak">\n            {props.listing.item.publisher?.name ?? props.listing.catalog.publisher?.name ?? "Unknown publisher"} · v\n            {props.listing.item.version} · {props.listing.source.name}\n          </div>\n        </div>\n        <button\n          type="button"\n          disabled={props.busy}\n          class="shrink-0 rounded-md bg-surface-raised-base px-3 py-1.5 text-12-medium text-text-strong hover:bg-surface-raised-base-hover disabled:opacity-50"\n          onClick={props.action}\n        >\n          {status() === "available" ? "Install" : status() === "update" ? "Update" : "Uninstall"}\n        </button>\n      </div>\n      <p class="mt-4 whitespace-pre-wrap text-13-regular leading-5 text-text-base">{props.listing.item.description}</p>\n      <Show when={installed()}>\n        <div class="mt-5 rounded-lg border border-border-weak">\n          <ToggleRow\n            title={language.t("marketplace.component.plugin.title")}\n            description={language.t("marketplace.component.plugin.description")}\n            checked={enabled()}\n            disabled={props.busy}\n            change={(checked) =>\n              props.toggle(\n                "package",\n                undefined,\n                checked,\n                `${checked ? "Enabled" : "Disabled"} ${props.listing.item.name}`,\n              )\n            }\n          />\n          <For each={skills()}>\n            {(skill) => {\n              const checked = () => marketplaceSkillEnabled(props.config, props.listing.key, skill.id)\n              return (\n                <ToggleRow\n                  title={skill.name}\n                  description={skill.description ?? skill.path ?? skill.url ?? "Marketplace skill"}\n                  checked={checked()}\n                  disabled={props.busy || !enabled()}\n                  change={(value) =>\n                    props.toggle("skill", skill.id, value, `${value ? "Enabled" : "Disabled"} skill ${skill.name}`)\n                  }\n                />\n              )\n            }}\n          </For>\n          <For each={mcp()}>\n            {(name) => {\n              const checked = () => marketplaceMcpEnabled(props.config, props.listing.key, name)\n              return (\n                <ToggleRow\n                  title={name}\n                  description="MCP server"\n                  checked={checked()}\n                  disabled={props.busy || !enabled()}\n                  change={(value) =>\n                    props.toggle("mcp", name, value, `${value ? "Enabled" : "Disabled"} MCP server ${name}`)\n                  }\n                />\n              )\n            }}\n          </For>\n        </div>\n      </Show>\n      <div class="mt-5 grid grid-cols-2 gap-3 text-12-regular">\n        <Meta label="Changes" value={marketplacePlanSummary(props.listing.item.install)} />\n        <Meta label="Trust" value={props.listing.source.trust ?? "community"} />\n        <Meta label="License" value={props.listing.item.license ?? "Not specified"} />\n        <Meta label="Catalog digest" value={props.listing.catalog_digest ?? "Built-in or not cached"} />\n      </div>\n    </div>\n  )\n}\n\nfunction ToggleRow(props: {\n  title: string\n  description: string\n  checked: boolean\n  disabled: boolean\n  change: (value: boolean) => void\n}) {\n  return (\n    <div class="flex items-center justify-between gap-4 border-b border-border-weak p-3 last:border-b-0">\n      <div>\n        <div class="text-13-medium text-text-strong">{props.title}</div>\n        <div class="mt-0.5 text-11-regular text-text-weak">{props.description}</div>\n      </div>\n      <Switch checked={props.checked} disabled={props.disabled} onChange={props.change} />\n    </div>\n  )\n}\n\nfunction Meta(props: { label: string; value: string }) {\n  return (\n    <div>\n      <div class="text-11-medium uppercase text-text-weak">{props.label}</div>\n      <div class="mt-1 break-all text-text-base">{props.value}</div>\n    </div>\n  )\n}\n\nfunction Sources(props: {\n  sources: MarketplaceSource[]\n  errors: MarketplaceView["errors"]\n  busy: boolean\n  sourceURL: string\n  sourceName: string\n  sourceTrust: MarketplaceConfiguredTrust\n  setURL: (value: string) => void\n  setName: (value: string) => void\n  setTrust: (value: MarketplaceConfiguredTrust) => void\n  add: () => void\n  toggle: (source: MarketplaceSource) => void\n  remove: (source: MarketplaceSource) => void\n}) {\n  return (\n    <div class="min-h-0 flex-1 overflow-y-auto">\n      <div class="grid gap-2 rounded-lg border border-border-weak bg-surface-base p-3 md:grid-cols-[1fr_13rem_9rem_auto]">\n        <input\n          value={props.sourceURL}\n          onInput={(event) => props.setURL(event.currentTarget.value)}\n          placeholder="https://… or github:owner/repository"\n          class="rounded-md border border-border-base bg-background-base px-2.5 py-1.5 text-13-regular text-text-strong"\n        />\n        <input\n          value={props.sourceName}\n          onInput={(event) => props.setName(event.currentTarget.value)}\n          placeholder="Display name"\n          class="rounded-md border border-border-base bg-background-base px-2.5 py-1.5 text-13-regular text-text-strong"\n        />\n        <select\n          value={props.sourceTrust}\n          onChange={(event) => props.setTrust(event.currentTarget.value as MarketplaceConfiguredTrust)}\n          class="rounded-md border border-border-base bg-background-base px-2.5 py-1.5 text-13-regular text-text-strong"\n        >\n          <option value="community">community</option>\n          <option value="private">private</option>\n        </select>\n        <button\n          type="button"\n          disabled={props.busy || !props.sourceURL.trim()}\n          class="rounded-md bg-surface-raised-base px-3 py-1.5 text-12-medium text-text-strong disabled:opacity-50"\n          onClick={props.add}\n        >\n          Add\n        </button>\n      </div>\n      <div class="mt-3 space-y-2">\n        <For each={props.sources}>\n          {(source) => {\n            const locked = source.id === OFFICIAL_MARKETPLACE_SOURCE.id\n            return (\n              <div class="flex items-center justify-between gap-4 rounded-lg border border-border-weak bg-surface-base p-3">\n                <div class="min-w-0">\n                  <div class="flex items-center gap-2">\n                    <span class="text-13-medium text-text-strong">{source.name}</span>\n                    <span class="text-10-medium uppercase text-text-weak">{source.trust ?? "community"}</span>\n                  </div>\n                  <div class="mt-1 truncate text-11-regular text-text-weak">{source.reference ?? source.url}</div>\n                </div>\n                <div class="flex items-center gap-2">\n                  <Switch\n                    checked={source.enabled !== false}\n                    disabled={props.busy}\n                    onChange={() => props.toggle(source)}\n                  />\n                  <button\n                    type="button"\n                    disabled={props.busy || locked}\n                    class="rounded-md px-2 py-1 text-12-medium text-text-base hover:bg-surface-raised-base-hover disabled:opacity-40"\n                    onClick={() => props.remove(source)}\n                  >\n                    Remove\n                  </button>\n                </div>\n              </div>\n            )\n          }}\n        </For>\n      </div>\n      <Show when={props.errors.length}>\n        <div class="mt-3 rounded-md border border-border-warning p-3 text-12-regular text-text-base">\n          <For each={props.errors}>{(error) => <div>{error.source.name}: {error.message}</div>}</For>\n        </div>\n      </Show>\n    </div>\n  )\n}\n\nfunction formatBytes(bytes: number) {\n  if (bytes < 1024) return `${bytes} B`\n  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KiB`\n  return `${(bytes / (1024 * 1024)).toFixed(1)} MiB`\n}\n')

write('packages/tui/src/feature-plugins/system/marketplace.tsx', 'import type { TuiPlugin, TuiPluginApi } from "@opencode-ai/plugin/tui"\nimport {\n  OFFICIAL_MARKETPLACE_SOURCE,\n  marketplaceItemEnabled,\n  marketplaceMcpEnabled,\n  marketplacePermissions,\n  marketplacePlanSummary,\n  marketplaceSkillComponents,\n  marketplaceSkillEnabled,\n  marketplaceSources,\n  marketplaceStatus,\n  type MarketplaceMutationResult,\n  type MarketplacePlanResult,\n  type MarketplaceView,\n} from "@opencode-ai/core/marketplace"\nimport { createMemo, createResource } from "solid-js"\nimport { DialogSelect, type DialogSelectOption } from "../../ui/dialog-select"\nimport { useBindings } from "../../keymap"\nimport { errorMessage } from "../../util/error"\nimport type { BuiltinTuiPlugin } from "../builtins"\n\nconst id = "internal:marketplace"\n\nfunction confirm(api: TuiPluginApi, title: string, message: string) {\n  return new Promise<boolean>((resolve) => {\n    api.ui.dialog.replace(\n      () => (\n        <api.ui.DialogConfirm\n          title={title}\n          message={message}\n          onConfirm={() => resolve(true)}\n          onCancel={() => resolve(false)}\n        />\n      ),\n      () => resolve(false),\n    )\n  })\n}\n\nfunction prompt(api: TuiPluginApi, title: string, placeholder: string) {\n  return new Promise<string | undefined>((resolve) => {\n    api.ui.dialog.replace(\n      () => (\n        <api.ui.DialogPrompt\n          title={title}\n          placeholder={placeholder}\n          onConfirm={(value) => resolve(value)}\n          onCancel={() => resolve(undefined)}\n        />\n      ),\n      () => resolve(undefined),\n    )\n  })\n}\n\nasync function unwrap<T>(request: Promise<{ data?: T; error?: unknown }>): Promise<T> {\n  const result = await request\n  if (result.error) throw new Error(errorMessage(result.error))\n  if (result.data === undefined) throw new Error("Marketplace server returned no data")\n  return result.data\n}\n\nconst getView = (api: TuiPluginApi, refresh = false) =>\n  unwrap<MarketplaceView>(refresh ? api.client.marketplace.refresh() : api.client.marketplace.get())\n\nfunction statusText(api: TuiPluginApi, view: MarketplaceView, key: string) {\n  const listing = view.listings.find((candidate) => candidate.key === key)\n  if (!listing) return ""\n  const status = marketplaceStatus({ marketplace: view.state }, listing)\n  const color =\n    status === "update"\n      ? api.theme.current.warning\n      : status === "installed"\n        ? api.theme.current.success\n        : api.theme.current.textMuted\n  return <span style={{ fg: color }}>{status}</span>\n}\n\nfunction details(listing: MarketplaceView["listings"][number]) {\n  return [\n    listing.item.description,\n    `publisher: ${listing.item.publisher?.name ?? listing.catalog.publisher?.name ?? "unknown"}`,\n    `version: ${listing.item.version}`,\n    `catalog: ${listing.source.name} (${listing.source.trust ?? "community"})`,\n    listing.catalog_digest ? `catalog digest: ${listing.catalog_digest}` : undefined,\n    listing.orphaned ? "catalog status: unavailable; local install remains manageable" : undefined,\n    `changes: ${marketplacePlanSummary(listing.item.install)}`,\n    ...marketplacePermissions(listing.item).map((permission) => `permission: ${permission}`),\n  ].filter((value): value is string => value !== undefined)\n}\n\nasync function applyMutation(\n  api: TuiPluginApi,\n  request: Promise<{ data?: MarketplaceMutationResult; error?: unknown }>,\n  message: string,\n) {\n  try {\n    const result = await unwrap(request)\n    if (!result.ok) {\n      api.ui.toast({ variant: "error", message: result.message })\n      return false\n    }\n    await Promise.allSettled(result.connect_mcp.map((name) => api.client.mcp.connect({ name })))\n    api.ui.toast({ variant: "success", message })\n    if (result.preserved.length) {\n      api.ui.toast({ variant: "warning", message: `Kept modified settings: ${result.preserved.join(", ")}` })\n    }\n    return true\n  } catch (error) {\n    api.ui.toast({ variant: "error", message: errorMessage(error) })\n    return false\n  }\n}\n\nfunction View(props: { api: TuiPluginApi }) {\n  const [data, actions] = createResource(() => getView(props.api))\n  const rows = createMemo<DialogSelectOption<string>[]>(() =>\n    (data()?.listings ?? []).map((listing) => ({\n      title: listing.item.name,\n      value: listing.key,\n      category: `${listing.item.kind} · ${listing.source.name}`,\n      description: listing.item.description,\n      details: details(listing),\n      footer: data() ? statusText(props.api, data()!, listing.key) : "",\n    })),\n  )\n  let current: string | undefined\n\n  async function apply(key: string) {\n    const view = data()\n    const listing = view?.listings.find((candidate) => candidate.key === key)\n    if (!view || !listing) return\n    const status = marketplaceStatus({ marketplace: view.state }, listing)\n    if (status === "installed") {\n      showComponents(props.api, key)\n      return\n    }\n\n    try {\n      const planned = await unwrap<MarketplacePlanResult>(props.api.client.marketplace.plan({ key }))\n      if (!planned.ok) {\n        props.api.ui.toast({ variant: "error", message: planned.message })\n        show(props.api)\n        return\n      }\n      const message = [\n        planned.summary,\n        planned.trust_warning ? `Catalog trust: ${listing.source.trust ?? "community"}.` : undefined,\n        planned.permissions.length ? `Capabilities: ${planned.permissions.join("; ")}.` : undefined,\n        planned.conflicts.length ? `Shadow: ${planned.conflicts.map((item) => item.path).join(", ")}.` : undefined,\n      ]\n        .filter((value): value is string => value !== undefined)\n        .join("\\n")\n      if (!(await confirm(props.api, `${planned.action === "update" ? "Update" : "Install"} ${listing.item.name}?`, message))) {\n        show(props.api)\n        return\n      }\n      await applyMutation(\n        props.api,\n        props.api.client.marketplace.install({\n          key,\n          expected_revision: view.state.revision ?? 0,\n          force: planned.conflicts.length > 0,\n          accept_untrusted: planned.trust_warning,\n        }),\n        `${planned.action === "update" ? "Updated" : "Installed"} ${listing.item.name}`,\n      )\n    } catch (error) {\n      props.api.ui.toast({ variant: "error", message: errorMessage(error) })\n    }\n    show(props.api)\n  }\n\n  async function updateAll() {\n    const view = data()\n    if (!view) return\n    const result = await applyMutation(\n      props.api,\n      props.api.client.marketplace.updateAll({\n        expected_revision: view.state.revision ?? 0,\n        force: false,\n        accept_untrusted: false,\n      }),\n      "Updated Marketplace packages",\n    )\n    if (result) await actions.refetch()\n  }\n\n  async function prune() {\n    try {\n      const summary = await unwrap(props.api.client.marketplace.cachePrune({ max_age_days: 30 }))\n      props.api.ui.toast({\n        variant: "success",\n        message: `Cache: ${summary.objects} objects, ${summary.total_bytes} bytes`,\n      })\n    } catch (error) {\n      props.api.ui.toast({ variant: "error", message: errorMessage(error) })\n    }\n    show(props.api)\n  }\n\n  useBindings(() => ({\n    bindings: [\n      { key: "ctrl+r", desc: "Refresh marketplace", group: "Marketplace", cmd: () => void actions.refetch() },\n      { key: "ctrl+s", desc: "Open marketplace sources", group: "Marketplace", cmd: () => showSources(props.api) },\n      { key: "ctrl+u", desc: "Update all marketplace items", group: "Marketplace", cmd: () => void updateAll() },\n      { key: "ctrl+p", desc: "Prune marketplace cache", group: "Marketplace", cmd: () => void prune() },\n      {\n        key: "space",\n        desc: "Enable or disable installed package",\n        group: "Marketplace",\n        cmd: () => {\n          const view = data()\n          const listing = view?.listings.find((candidate) => candidate.key === current)\n          if (!view || !listing || marketplaceStatus({ marketplace: view.state }, listing) === "available") return\n          const enabled = !marketplaceItemEnabled({ marketplace: view.state }, listing.key)\n          void applyMutation(\n            props.api,\n            props.api.client.marketplace.toggle({\n              key: listing.key,\n              expected_revision: view.state.revision ?? 0,\n              component: "package",\n              enabled,\n            }),\n            `${enabled ? "Enabled" : "Disabled"} ${listing.item.name}`,\n          ).then(() => show(props.api))\n        },\n      },\n    ],\n  }))\n\n  return (\n    <DialogSelect\n      title="Marketplace"\n      placeholder="Search plugins, skills, agents, commands, MCP servers…"\n      options={rows()}\n      onMove={(option) => (current = option.value)}\n      emptyView={\n        <box paddingLeft={2} paddingRight={2} paddingBottom={1} gap={1}>\n          <text fg={props.api.theme.current.textMuted}>\n            {data.loading\n              ? "Loading cached catalogs…"\n              : data.error\n                ? errorMessage(data.error)\n                : "No Marketplace items. Add a catalog with Marketplace: Sources."}\n          </text>\n        </box>\n      }\n      footer={\n        <box flexDirection="column">\n          <text fg={props.api.theme.current.textMuted}>\n            ctrl+r refresh · ctrl+s sources · ctrl+u update · ctrl+p prune · space enable/disable\n          </text>\n          {data() ? (\n            <text fg={props.api.theme.current.textMuted}>\n              revision {data()!.state.revision ?? 0} · {data()!.cache.objects} cached objects\n            </text>\n          ) : null}\n          {data()?.errors.length ? (\n            <text fg={props.api.theme.current.warning}>\n              {data()!\n                .errors.map((error) => `${error.source.name}: ${error.message}`)\n                .join(" · ")}\n            </text>\n          ) : null}\n        </box>\n      }\n      onSelect={(option) => void apply(option.value)}\n    />\n  )\n}\n\nfunction Components(props: { api: TuiPluginApi; key: string }) {\n  const [view] = createResource(() => getView(props.api))\n  const listing = () => view()?.listings.find((candidate) => candidate.key === props.key)\n  const installed = () => view()?.state.installed?.[props.key]\n  const rows = createMemo<DialogSelectOption<string>[]>(() => {\n    const state = installed()\n    const item = listing()\n    const data = view()\n    if (!state || !item || !data) return []\n    const config = { marketplace: data.state }\n    const packageEnabled = marketplaceItemEnabled(config, props.key)\n    return [\n      {\n        title: item.item.name,\n        value: "package",\n        category: "Package",\n        description: "Enable or disable every capability in this package.",\n        details: [`status: ${packageEnabled ? "enabled" : "disabled"}`],\n        footer: packageEnabled ? "enabled" : "disabled",\n      },\n      ...marketplaceSkillComponents(state.plan).map((skill) => {\n        const enabled = marketplaceSkillEnabled(config, props.key, skill.id)\n        return {\n          title: skill.name,\n          value: `skill:${skill.id}`,\n          category: "Skills",\n          description: skill.description ?? skill.path ?? skill.url,\n          details: [`status: ${enabled ? "enabled" : "disabled"}`],\n          footer: enabled ? "enabled" : "disabled",\n        }\n      }),\n      ...Object.keys(state.plan.mcp ?? {}).map((name) => {\n        const enabled = marketplaceMcpEnabled(config, props.key, name)\n        return {\n          title: name,\n          value: `mcp:${name}`,\n          category: "MCP servers",\n          description: "Managed MCP server",\n          details: [`status: ${enabled ? "enabled" : "disabled"}`],\n          footer: enabled ? "enabled" : "disabled",\n        }\n      }),\n    ]\n  })\n\n  async function remove() {\n    const data = view()\n    const item = listing()\n    if (!data || !item) return\n    if (!(await confirm(props.api, `Remove ${item.item.name}?`, "The local SQLite install record will be removed."))) {\n      showComponents(props.api, props.key)\n      return\n    }\n    await applyMutation(\n      props.api,\n      props.api.client.marketplace.uninstall({\n        key: props.key,\n        expected_revision: data.state.revision ?? 0,\n      }),\n      `Removed ${item.item.name}`,\n    )\n    show(props.api)\n  }\n\n  async function toggle(value: string) {\n    const data = view()\n    const item = listing()\n    if (!data || !item) return\n    const config = { marketplace: data.state }\n    const component = value === "package" ? "package" : value.startsWith("skill:") ? "skill" : "mcp"\n    const componentID = component === "package" ? undefined : value.slice(value.indexOf(":") + 1)\n    const enabled =\n      component === "package"\n        ? !marketplaceItemEnabled(config, props.key)\n        : component === "skill"\n          ? !marketplaceSkillEnabled(config, props.key, componentID!)\n          : !marketplaceMcpEnabled(config, props.key, componentID!)\n    await applyMutation(\n      props.api,\n      props.api.client.marketplace.toggle({\n        key: props.key,\n        expected_revision: data.state.revision ?? 0,\n        component,\n        id: componentID,\n        enabled,\n      }),\n      `${enabled ? "Enabled" : "Disabled"} ${componentID ?? item.item.name}`,\n    )\n    showComponents(props.api, props.key)\n  }\n\n  useBindings(() => ({\n    bindings: [\n      { key: "ctrl+b", desc: "Back to marketplace", group: "Marketplace", cmd: () => show(props.api) },\n      { key: "ctrl+d", desc: "Uninstall package", group: "Marketplace", cmd: () => void remove() },\n    ],\n  }))\n\n  return (\n    <DialogSelect\n      title={`${listing()?.item.name ?? "Marketplace"} components`}\n      options={rows()}\n      footer={<text fg={props.api.theme.current.textMuted}>enter toggle · ctrl+d uninstall · ctrl+b back</text>}\n      onSelect={(option) => void toggle(option.value)}\n    />\n  )\n}\n\nfunction Sources(props: { api: TuiPluginApi }) {\n  const [view] = createResource(() => getView(props.api))\n  const sources = () => (view() ? marketplaceSources({ marketplace: view()!.state }) : [])\n  const rows = createMemo<DialogSelectOption<string>[]>(() =>\n    sources().map((source) => ({\n      title: source.name,\n      value: source.id,\n      category: source.trust ?? "community",\n      description: source.reference ?? source.url,\n      details: [`status: ${source.enabled === false ? "disabled" : "enabled"}`],\n      footer: source.enabled === false ? "disabled" : "enabled",\n    })),\n  )\n  let current: string | undefined\n\n  async function add() {\n    const raw = await prompt(props.api, "Add marketplace catalog", "URL or github:owner/repository")\n    const data = view()\n    if (!raw?.trim() || !data) {\n      showSources(props.api)\n      return\n    }\n    await applyMutation(\n      props.api,\n      props.api.client.marketplace.sourceAdd({\n        expected_revision: data.state.revision ?? 0,\n        url: raw.trim(),\n        trust: "community",\n      }),\n      "Marketplace source added",\n    )\n    showSources(props.api)\n  }\n\n  async function remove() {\n    const data = view()\n    const source = sources().find((candidate) => candidate.id === current)\n    if (!data || !source || source.id === OFFICIAL_MARKETPLACE_SOURCE.id) return\n    if (!(await confirm(props.api, `Remove ${source.name}?`, "Installed packages remain available from local state."))) {\n      showSources(props.api)\n      return\n    }\n    await applyMutation(\n      props.api,\n      props.api.client.marketplace.sourceRemove({\n        id: source.id,\n        expected_revision: data.state.revision ?? 0,\n      }),\n      `Removed ${source.name}`,\n    )\n    showSources(props.api)\n  }\n\n  useBindings(() => ({\n    bindings: [\n      { key: "ctrl+a", desc: "Add marketplace source", group: "Marketplace", cmd: () => void add() },\n      { key: "ctrl+d", desc: "Remove marketplace source", group: "Marketplace", cmd: () => void remove() },\n      { key: "ctrl+b", desc: "Back to marketplace", group: "Marketplace", cmd: () => show(props.api) },\n    ],\n  }))\n\n  return (\n    <DialogSelect\n      title="Marketplace sources"\n      options={rows()}\n      onMove={(option) => (current = option.value)}\n      footer={\n        <text fg={props.api.theme.current.textMuted}>\n          ctrl+a add · ctrl+d remove · ctrl+b back · enter enable/disable\n        </text>\n      }\n      onSelect={(option) => {\n        const data = view()\n        const source = sources().find((candidate) => candidate.id === option.value)\n        if (!data || !source) return\n        void applyMutation(\n          props.api,\n          props.api.client.marketplace.sourceToggle({\n            id: source.id,\n            expected_revision: data.state.revision ?? 0,\n            enabled: source.enabled === false,\n          }),\n          `${source.enabled === false ? "Enabled" : "Disabled"} ${source.name}`,\n        ).then(() => showSources(props.api))\n      }}\n    />\n  )\n}\n\nfunction show(api: TuiPluginApi) {\n  api.ui.dialog.replace(() => <View api={api} />)\n}\n\nfunction showSources(api: TuiPluginApi) {\n  api.ui.dialog.replace(() => <Sources api={api} />)\n}\n\nfunction showComponents(api: TuiPluginApi, key: string) {\n  api.ui.dialog.replace(() => <Components api={api} key={key} />)\n}\n\nconst tui: TuiPlugin = async (api) => {\n  api.keymap.registerLayer({\n    commands: [\n      {\n        name: "marketplace.open",\n        title: "Marketplace",\n        category: "System",\n        namespace: "palette",\n        run() {\n          setTimeout(() => show(api), 0)\n        },\n      },\n      {\n        name: "marketplace.sources",\n        title: "Marketplace sources",\n        category: "System",\n        namespace: "palette",\n        run() {\n          setTimeout(() => showSources(api), 0)\n        },\n      },\n    ],\n  })\n}\n\nconst plugin: BuiltinTuiPlugin = { id, tui }\nexport default plugin\n')

write('packages/opencode/test/marketplace/registry.test.ts', 'import { beforeEach, describe, expect } from "bun:test"\nimport { Effect } from "effect"\nimport { sql } from "drizzle-orm"\nimport { LayerNode } from "@opencode-ai/core/effect/layer-node"\nimport { Database } from "@opencode-ai/core/database/database"\nimport { testEffect } from "../lib/effect"\nimport * as MarketplaceRegistry from "@/marketplace/registry"\n\nconst layer = LayerNode.compile(LayerNode.group([Database.node, MarketplaceRegistry.node]))\nconst it = testEffect(layer)\n\nbeforeEach(async () => {\n  await Effect.runPromise(\n    Effect.gen(function* () {\n      const { db } = yield* Database.Service\n      yield* db.run(sql`DELETE FROM marketplace_install`).pipe(Effect.orDie)\n      yield* db.run(sql`DELETE FROM marketplace_source`).pipe(Effect.orDie)\n      yield* db.run(sql`DELETE FROM marketplace_registry`).pipe(Effect.orDie)\n    }).pipe(Effect.provide(layer)),\n  )\n})\n\ndescribe("marketplace sqlite registry", () => {\n  it.effect("stores ordered sources and installs with a monotonic revision", () =>\n    Effect.gen(function* () {\n      const registry = yield* MarketplaceRegistry.Service\n      expect(yield* registry.read()).toEqual({ revision: 0 })\n\n      const first = yield* registry.replace({\n        revision: 0,\n        sources: [\n          { id: "b", name: "B", url: "https://b.example/catalog.json" },\n          { id: "a", name: "A", url: "https://a.example/catalog.json" },\n        ],\n        installed: {\n          "source:catalog:item": {\n            source: "source",\n            catalog: "catalog",\n            item: "item",\n            name: "Item",\n            kind: "bundle",\n            version: "1.0.0",\n            fingerprint: "fingerprint",\n            installed_at: "2026-07-30T00:00:00.000Z",\n            updated_at: "2026-07-30T00:00:00.000Z",\n            plan: { commands: { review: { template: "review" } } },\n            active_plan: { commands: { review: { template: "review" } } },\n            receipt: {},\n          },\n        },\n      })\n\n      expect(first.changed).toBe(true)\n      expect(first.state.revision).toBe(1)\n      const read = yield* registry.read()\n      expect(read.sources?.map((source) => source.id)).toEqual(["b", "a"])\n      expect(Object.keys(read.installed ?? {})).toEqual(["source:catalog:item"])\n    }),\n  )\n\n  it.effect("rejects stale writes and treats identical writes as no-ops", () =>\n    Effect.gen(function* () {\n      const registry = yield* MarketplaceRegistry.Service\n      const first = yield* registry.replace({\n        revision: 0,\n        sources: [{ id: "a", name: "A", url: "https://a.example/catalog.json" }],\n      })\n      const noop = yield* registry.replace(first.state)\n      expect(noop.changed).toBe(false)\n      expect(noop.state.revision).toBe(1)\n\n      const stale = yield* Effect.exit(\n        registry.replace({\n          revision: 0,\n          sources: [{ id: "b", name: "B", url: "https://b.example/catalog.json" }],\n        }),\n      )\n      expect(stale._tag).toBe("Failure")\n      expect((yield* registry.read()).sources?.map((source) => source.id)).toEqual(["a"])\n    }),\n  )\n})\n')

write('packages/opencode/test/marketplace/cache.test.ts', 'import fs from "fs/promises"\nimport { beforeEach, describe, expect } from "bun:test"\nimport { Effect } from "effect"\nimport { sql } from "drizzle-orm"\nimport { LayerNode } from "@opencode-ai/core/effect/layer-node"\nimport { Database } from "@opencode-ai/core/database/database"\nimport { testEffect } from "../lib/effect"\nimport * as MarketplaceCache from "@/marketplace/cache"\n\nconst layer = LayerNode.compile(LayerNode.group([Database.node, MarketplaceCache.node]))\nconst it = testEffect(layer)\n\nbeforeEach(async () => {\n  await Effect.runPromise(\n    Effect.gen(function* () {\n      const { db } = yield* Database.Service\n      yield* db.run(sql`DELETE FROM marketplace_fetch`).pipe(Effect.orDie)\n      yield* db.run(sql`DELETE FROM marketplace_materialization`).pipe(Effect.orDie)\n      yield* db.run(sql`DELETE FROM marketplace_artifact`).pipe(Effect.orDie)\n    }).pipe(Effect.provide(layer)),\n  )\n})\n\ndescribe("marketplace content-addressed cache", () => {\n  it.effect("deduplicates identical bytes by sha256 digest", () =>\n    Effect.gen(function* () {\n      const cache = yield* MarketplaceCache.Service\n      const bytes = new TextEncoder().encode("same artifact")\n      const first = yield* cache.put(bytes, { kind: "test" })\n      const second = yield* cache.put(bytes, { kind: "test" })\n      expect(first.digest).toBe(second.digest)\n      expect(first.path).toBe(second.path)\n      expect((yield* cache.summary()).objects).toBe(1)\n    }),\n  )\n\n  it.effect("materializes a remote skill into an immutable local tree", () =>\n    Effect.acquireUseRelease(\n      Effect.sync(() =>\n        Bun.serve({\n          port: 0,\n          fetch(request) {\n            const url = new URL(request.url)\n            if (url.pathname.endsWith("/index.json")) return new Response("not found", { status: 404 })\n            if (url.pathname.endsWith("/skill.md")) {\n              return new Response("---\\nname: review\\ndescription: Review changes\\n---\\nReview the current diff.", {\n                headers: { "content-type": "text/markdown" },\n              })\n            }\n            return new Response("not found", { status: 404 })\n          },\n        }),\n      ),\n      (server) =>\n        Effect.gen(function* () {\n          const cache = yield* MarketplaceCache.Service\n          const url = new URL("skill.md", server.url).href\n          const materialized = yield* cache.materializePlan(\n            {\n              skills: {\n                items: [{ id: "review", name: "review", url }],\n              },\n            },\n            {\n              id: "local",\n              name: "Local",\n              url: new URL("catalog.json", server.url).href,\n              trust: "private",\n            },\n          )\n          const item = materialized.plan.skills?.items?.[0]\n          expect(item?.url).toBeUndefined()\n          expect(item?.path).toBeDefined()\n          expect(await fs.readFile(`${item!.path}/SKILL.md`, "utf8")).toContain("Review the current diff")\n          expect(materialized.treeDigest).toMatch(/^sha256:/)\n          expect(materialized.artifactDigests.length).toBeGreaterThan(0)\n        }),\n      (server) => Effect.promise(async () => void (await server.stop(true))),\n    ),\n  )\n})\n')

