sub('packages/opencode/test/config/config.test.ts', 'it\\.effect\\("stores marketplace installs outside the global json config"[\\s\\S]*?\\n(?=it\\.instance\\()', 'it.effect("stores marketplace installs in SQLite outside the global json config", () =>\n  withGlobalConfig(\n    {\n      config: {\n        command: {\n          keep: { template: "keep" },\n        },\n      },\n    },\n    ({ dir }) =>\n      Effect.gen(function* () {\n        const registry = yield* MarketplaceRegistry.Service\n        const file = path.join(dir, "opencode.json")\n        const before = yield* FSUtil.use.readFileString(file)\n        const plan = { commands: { review: { template: "review" } } }\n        const stored = yield* registry.replace({\n          revision: 0,\n          installed: {\n            "community:tools:review": {\n              source: "community",\n              catalog: "tools",\n              item: "review",\n              name: "Review",\n              kind: "command",\n              version: "1.0.0",\n              fingerprint: "review-v1",\n              installed_at: "2026-07-29T00:00:00.000Z",\n              updated_at: "2026-07-29T00:00:00.000Z",\n              plan,\n              active_plan: plan,\n              receipt: {},\n            },\n          },\n        })\n        yield* Config.use.invalidate()\n\n        const result = yield* Config.use.getGlobal()\n        expect(yield* FSUtil.use.readFileString(file)).toBe(before)\n        expect(result.command).toEqual({ keep: { template: "keep" }, review: { template: "review" } })\n        expect(result.marketplace?.revision).toBe(stored.state.revision)\n        expect((yield* registry.read()).installed?.["community:tools:review"]?.item).toBe("review")\n        expect(yield* FSUtil.use.existsSafe(path.join(Global.Path.data, "marketplace", "registry.json"))).toBe(false)\n      }),\n  ),\n)\n\nit.effect("stores marketplace sources in SQLite outside jsonc without changing comments", () =>\n  withGlobalConfig(\n    {\n      config: {\n        model: "test/model",\n      },\n      name: "opencode.jsonc",\n    },\n    ({ dir }) =>\n      Effect.gen(function* () {\n        const registry = yield* MarketplaceRegistry.Service\n        const file = path.join(dir, "opencode.jsonc")\n        const before = yield* FSUtil.use.readFileString(file)\n        const result = yield* registry.replace({\n          revision: 0,\n          sources: [\n            {\n              id: "community",\n              name: "Community",\n              url: "https://example.test/catalog.json",\n              trust: "community",\n            },\n          ],\n        })\n        yield* Config.use.invalidate()\n\n        expect(yield* FSUtil.use.readFileString(file)).toBe(before)\n        const effective = yield* Config.use.getGlobal()\n        expect(effective.marketplace?.sources?.map((source) => source.id)).toEqual(["community"])\n        expect(effective.marketplace?.revision).toBe(result.state.revision)\n      }),\n  ),\n)\n\n', flags=re.MULTILINE)

target = Path('packages/web/src/content/docs/marketplace.mdx')
text = target.read_text()
if '## Local registry, artifact cache, and API' not in text:
    target.write_text(text.rstrip() + '\n\n## Local registry, artifact cache, and API\n\nMarketplace runtime state is stored in the OpenCode SQLite database. Sources, installed packages, component switches,\nartifact references, and the monotonic registry revision are application state and are never written to\n`opencode.json` or `opencode.jsonc`.\n\nCatalog responses, exact item manifests, icons, remote skill files, and remote instruction files are stored in a\nSHA-256 content-addressed cache under the OpenCode cache directory. Remote skills and instructions are materialized\ninto immutable local trees before their install plan becomes active. Catalog refresh uses conditional HTTP requests\nwhen ETag or Last-Modified metadata is available and falls back to the last validated cached response while offline.\n\nThe desktop app and TUI use the dedicated `/marketplace` API. Every mutation sends the revision it observed. A stale\nclient receives a revision conflict instead of silently overwriting another client. Installation and update also\nseparate planning from execution so trust warnings and configuration conflicts can be reviewed before executable\ncontent is activated.\n\nThis feature is still under development. OpenCode creates the Marketplace tables as part of the normal database\nschema migration, but it intentionally does not import state from experimental `registry.json` files or Marketplace\nconfiguration written by earlier development commits.\n\n' + '\n')
target = Path('packages/web/src/content/docs/ru/marketplace.mdx')
text = target.read_text()
if '## Локальный реестр, кэш артефактов и API' not in text:
    target.write_text(text.rstrip() + '\n\n## Локальный реестр, кэш артефактов и API\n\nRuntime-состояние Marketplace хранится в SQLite-базе OpenCode. Источники, установленные пакеты, переключатели\nкомпонентов, ссылки на артефакты и монотонная ревизия реестра являются состоянием приложения и никогда не записываются\nв `opencode.json` или `opencode.jsonc`.\n\nОтветы каталогов, точные манифесты элементов, иконки, удалённые файлы скилов и удалённые инструкции сохраняются в\ncontent-addressed кэше SHA-256 внутри каталога кэша OpenCode. Перед активацией install plan удалённые скилы и\nинструкции материализуются в неизменяемое локальное дерево. При обновлении каталога используются условные HTTP-запросы\nс ETag или Last-Modified, а при отсутствии сети OpenCode использует последний успешно проверенный ответ из кэша.\n\nДесктопное приложение и TUI работают через отдельный API `/marketplace`. Каждая мутация передаёт увиденную клиентом\nревизию. Устаревший клиент получает конфликт ревизий и не может незаметно перезаписать изменения другого клиента.\nПланирование отделено от установки и обновления, поэтому предупреждения о доверии и конфликты конфигурации можно\nпроверить до активации исполняемого содержимого.\n\nФича пока находится в разработке. Таблицы Marketplace создаются обычной миграцией схемы базы данных, но импорт\nсостояния из экспериментальных `registry.json` или из Marketplace-конфигурации промежуточных коммитов намеренно не\nвыполняется.\n\n' + '\n')

